                .eq('congregation_id', 1) 
                .order("week_id", { ascending: true });

            // Use Promise.allSettled to handle potential failures in base program fetch
            // This is crucial because if congregation 1 is restricted or network issues occur for one query,
            // we should still try to load what we can.
