                localProgramPromise, 
                baseProgramPromise
            ]);

            const localProgramResult = results[0];
            const baseProgramResult = results[1];

            let localPrograms: ProgramData[] = [];
            let basePrograms: ProgramData[] = [];

            if (localProgramResult.status === 'fulfilled' && localProgramResult.value) {
              const { data: localData, error: localError } = localProgramResult.value;
              if (!localError && localData) {
