                .eq('access_token', accessKeyInput.trim())
                .single();

            if (error || !data) {
                setErrorMsg('Clave no válida o expirada.');
            } else {
                onSetSuperAdmin(false); // User logged in via key, NOT super admin
                // Success: Pass true to save to localStorage
                onTokenSuccess(data, true);
            }
        } catch (e) {
            setErrorMsg('Error de conexión.');
        } finally {
            setLoading(false);
        }
    };

    // --- LOGIC: SUPER ADMIN ---
    const handleAdminLogin = async () => {
        if (adminPassword === '980392925') {
            setLoading(true);
            await fetchCreatorList();
            setView('admin_dashboard');
            setAdminPassword('');
            setLoading(false);
        } else {
            setErrorMsg('Contraseña incorrecta');
        }
    };

    const fetchCreatorList = async () => {
        const { data, error } = await supabase.from('congregations').select('id, name').order('name');
        if (error) {
            alert('Error al cargar lista: ' + error.message);
        } else {
            setCreatorCongregations(data || []);
        }
    };

    const handleSelectCongregation = (c: {id: number, name: string}) => {
        // IMPORTANT: Clear any user token so next reload doesn't force user mode
        localStorage.removeItem('vmt_auto_token'); 
        onSetSuperAdmin(true); // User logged in via admin dashboard, IS super admin
        setCongregation(c);
        // Admin selects manually, no token needed, permissions set by AppContent default
    };

    const handleCreateCongregation = async () => {
        if (!newCongName.trim()) return;
        setLoading(true);
        const { data, error } = await supabase.from('congregations').insert([{ name: newCongName.trim() }]).select();
        if (!error && data) {
            await fetchCreatorList();
            await refreshCongregations();
            setNewCongName('');
            setIsCreating(false);
        } else {
            alert('Error: ' + (error?.message || 'Desconocido'));
        }
        setLoading(false);
    };

    // --- RENDERS ---

    const renderLogin = () => (
        <div style={{ animation: 'fadeIn 0.3s' }}>
            <h2 style={{fontSize:'1.5rem', fontWeight:'800', color:'#1e293b', textAlign:'center', marginBottom:'10px'}}>Bienvenido</h2>
            <p style={{fontSize:'0.95rem', color:'#64748b', textAlign:'center', marginBottom:'30px'}}>
                Ingresa tu llave de acceso para entrar a tu congregación.
            </p>

            <div style={{ marginBottom:'25px' }}>
                <input 
                    type="text" 
                    autoFocus 
                    value={accessKeyInput} 
                    onChange={e => setAccessKeyInput(e.target.value)} 
                    onKeyDown={e => e.key === 'Enter' && handleKeySubmit()} 
                    placeholder="Pegar llave de acceso aquí..." 
                    style={{ 
                        width: '100%', 
                        padding: '16px', 
                        borderRadius: '12px', 
                        border: `2px solid ${errorMsg ? '#ef4444' : '#cbd5e1'}`, 
                        fontSize: '1.1rem', 
                        textAlign: 'center', 
                        letterSpacing:'1px',
                        outline: 'none',
                        transition: 'border-color 0.2s',
                        boxShadow: '0 2px 5px rgba(0,0,0,0.05)'
                    }} 
                />
                {errorMsg && <p style={{color:'#ef4444', fontSize:'0.85rem', textAlign:'center', marginTop:'8px', fontWeight:'600'}}>{errorMsg}</p>}
            </div>

            <button 
                onClick={handleKeySubmit} 
                disabled={loading} 
                style={{ 
                    width: '100%', 
                    padding: '16px', 
                    backgroundColor: '#3b82f6', 
                    color: 'white', 
                    border: 'none', 
                    borderRadius: '12px', 
                    fontWeight: 'bold', 
                    fontSize: '1.1rem', 
                    cursor: 'pointer',
                    boxShadow: '0 4px 6px -1px rgba(59, 130, 246, 0.5)',
                    transition: 'transform 0.1s'
                }}
            >
                {loading ? <i className="fas fa-spinner fa-spin"></i> : 'Ingresar'}
            </button>

            <div style={{ marginTop: '40px', textAlign: 'center', borderTop: '1px solid #e2e8f0', paddingTop: '20px' }}>
                <button 
                    onClick={() => { setView('admin_login'); setErrorMsg(''); }} 
                    style={{ background: 'none', border: 'none', color: '#94a3b8', fontSize: '0.85rem', cursor: 'pointer', textDecoration: 'none', fontWeight: '500' }}
                >
                    <i className="fas fa-user-shield mr-1"></i> Soy Súper Administrador
                </button>
            </div>
        </div>
    );

    const renderAdminLogin = () => (
        <div style={{ animation: 'fadeIn 0.3s' }}>
            <h3 style={{fontSize:'1.2rem', marginBottom:'20px', color:'#334155', textAlign:'center'}}>Acceso Súper Administrador</h3>
            <input 
                type="password" 
                autoFocus 
                value={adminPassword} 
                onChange={e => setAdminPassword(e.target.value)} 
                onKeyDown={e => e.key === 'Enter' && handleAdminLogin()} 
                placeholder="Contraseña Maestra..." 
                style={{ width: '100%', padding: '14px', borderRadius: '12px', border: '2px solid #e2e8f0', fontSize: '1rem', marginBottom: '10px', textAlign: 'center' }} 
            />
            {errorMsg && <p style={{color:'#ef4444', fontSize:'0.85rem', textAlign:'center', marginBottom:'15px'}}>{errorMsg}</p>}

            <div style={{ display: 'flex', gap: '10px', marginTop:'20px' }}>
                <button onClick={() => { setView('login'); setAdminPassword(''); setErrorMsg(''); }} style={{ flex: 1, padding: '12px', backgroundColor: '#f1f5f9', color: '#475569', border: 'none', borderRadius: '12px', fontWeight: 'bold', cursor: 'pointer' }}>Volver</button>
                <button onClick={handleAdminLogin} style={{ flex: 1, padding: '12px', backgroundColor: '#3b82f6', color: 'white', border: 'none', borderRadius: '12px', fontWeight: 'bold', cursor: 'pointer' }}>Entrar</button>
            </div>
        </div>
    );

    const renderAdminDashboard = () => (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px', animation: 'fadeIn 0.3s' }}>
            <div style={{display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:'10px'}}>
                <h3 style={{fontSize:'1.1rem', margin:0, color:'#334155'}}>Panel de Control</h3>
                <button onClick={fetchCreatorList} style={{background:'none', border:'none', cursor:'pointer', color:'#3b82f6'}} title="Actualizar">
                    <i className={`fas fa-sync-alt ${loading ? 'fa-spin' : ''}`}></i>
                </button>
            </div>

            <div style={{maxHeight:'300px', overflowY:'auto', display:'flex', flexDirection:'column', gap:'10px'}}>
                {creatorCongregations.length === 0 && !loading && <p style={{textAlign:'center', color:'#94a3b8', padding:'10px'}}>No hay congregaciones.</p>}
                {creatorCongregations.map(c => (
                    <button key={c.id} onClick={() => handleSelectCongregation(c)} style={{ padding: '14px', backgroundColor: '#f8fafc', border: '1px solid #e2e8f0', borderRadius: '10px', textAlign: 'left', cursor: 'pointer', display: 'flex', justifyContent: 'space-between', alignItems: 'center', color: '#334155', fontWeight: '600', fontSize: '0.95rem' }}>
                        {c.name}
                        <i className="fas fa-chevron-right" style={{ color: '#cbd5e1' }}></i>
                    </button>
                ))}
            </div>

            <div style={{ borderTop: '1px solid #e2e8f0', margin: '10px 0' }}></div>

            {isCreating ? (
                <div style={{ animation: 'fadeIn 0.3s' }}>
                    <input type="text" autoFocus value={newCongName} onChange={e => setNewCongName(e.target.value)} placeholder="Nombre congregación..." style={{ width: '100%', padding: '12px', borderRadius: '10px', border: '1px solid #cbd5e1', marginBottom: '10px' }} />
                    <div style={{ display: 'flex', gap: '10px' }}>
                        <button onClick={() => setIsCreating(false)} style={{ flex: 1, padding: '10px', backgroundColor: '#f1f5f9', color: '#475569', border: 'none', borderRadius: '10px', fontWeight: 'bold', cursor: 'pointer' }}>Cancelar</button>
                        <button onClick={handleCreateCongregation} disabled={loading} style={{ flex: 1, padding: '10px', backgroundColor: '#10b981', color: 'white', border: 'none', borderRadius: '10px', fontWeight: 'bold', cursor: 'pointer' }}>Crear</button>
                    </div>
                </div>
            ) : (
                <button onClick={() => setIsCreating(true)} style={{ width: '100%', padding: '12px', backgroundColor: '#10b981', color: 'white', border: 'none', borderRadius: '10px', fontWeight: 'bold', cursor: 'pointer' }}><i className="fas fa-plus mr-2"></i> Nueva Congregación</button>
            )}

            <button onClick={() => setView('login')} style={{ width: '100%', padding: '12px', backgroundColor: '#f1f5f9', color: '#475569', border: 'none', borderRadius: '10px', fontWeight: 'bold', cursor: 'pointer', marginTop:'10px' }}>Cerrar Sesión</button>
        </div>
    );

    return (
        <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', backgroundColor: '#f8fafc', padding: '20px' }}>
            <div style={{ backgroundColor: 'white', padding: '40px', borderRadius: '24px', boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04)', maxWidth: '450px', width: '100%' }}>
                <div style={{ textAlign: 'center', marginBottom: '20px' }}>
                    <img src="https://images.unsplash.com/photo-1491841550275-ad7854e35ca6?auto=format&fit=crop&q=80&w=150&h=150" alt="Logo" style={{ width: '80px', height: '80px', borderRadius: '16px', objectFit: 'cover', margin: '0 auto 20px', display: 'block', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)' }} />
                </div>
                {view === 'login' && renderLogin()}
                {view === 'admin_login' && renderAdminLogin()}
                {view === 'admin_dashboard' && renderAdminDashboard()}
            </div>
        </div>
    );
};

// --- MAIN APP CONTENT ---
const AppContent: React.FC = () => {
    const { currentCongregation, setCongregation, loading } = useCongregation();

    // Default tabs for Admin (Everything is editable by default for admin)
    const defaultNavItems = [
        ...ALL_TABS,
        "Configuración" 
    ];

    const [navItems, setNavItems] = useState<string[]>(defaultNavItems);
    const [tabPermissions, setTabPermissions] = useState<{name: string, access: 'view' | 'edit'}[]>([]); 
    const [activeTab, setActiveTab] = useState<string>("Inicio");
    const [theme, setTheme] = useState<'light' | 'dark'>('light');
    const [viewMode, setViewMode] = useState<'desktop' | 'mobile'>('desktop');
    const [specialView, setSpecialView] = useState<{view: string; participant: string} | null>(null);
    const [isLoadingAccess, setIsLoadingAccess] = useState(true); // Start loading true to check persistent token
    const [accessLabel, setAccessLabel] = useState<string | null>(null);
    const [restrictedGroupId, setRestrictedGroupId] = useState<number | null>(null);

    // State to track if current session is super admin
    // Initialize from session storage to persist across reloads
    const [isSuperAdmin, setIsSuperAdmin] = useState(() => {
        return sessionStorage.getItem('vmt_is_super_admin') === 'true';
    });

    useEffect(() => {
        sessionStorage.setItem('vmt_is_super_admin', String(isSuperAdmin));

        // If becoming super admin, force full access and clear view label
        if (isSuperAdmin) {
            setNavItems(defaultNavItems);
            // Crucial: Clear the "View: ..." banner
            setAccessLabel(null);
            setRestrictedGroupId(null);
            setTabPermissions(defaultNavItems.map(t => ({ name: t, access: 'edit' })));
        }
    }, [isSuperAdmin]);

    // Apply Access Configuration Logic (Reused for URL token and Manual Token Entry)
    const applyAccessConfig = useCallback(async (data: any, saveToken?: boolean) => {
        if (!data) return;

        if (saveToken && data.access_token) {
            localStorage.setItem('vmt_auto_token', data.access_token);
        }

        setAccessLabel(data.label);
        if (data.restricted_group_id) {
            setRestrictedGroupId(data.restricted_group_id);
        }

        // When applying a token config, it's never a Super Admin session
        setIsSuperAdmin(false);

        // Ensure Congregation Context is set
        if (data.congregation_id) {
            const { data: congData } = await supabase
                .from('congregations')
                .select('*')
                .eq('id', data.congregation_id)
                .single();

            if (congData) {
                setCongregation(congData);
            }
        }

        // Parse permissions
        let rawTabs = data.visible_tabs;
        let permissions: any[] = [];
        let names: string[] = [];

        if (Array.isArray(rawTabs)) {
            rawTabs.forEach((t: any) => {
                if (typeof t === 'string') {
                    names.push(t);
                    permissions.push({ name: t, access: 'view' });
                } else if (t && typeof t === 'object' && t.name) {
                    names.push(t.name);
                    permissions.push({ name: t.name, access: t.access || 'view' });
                }
            });
        }

        setNavItems(names);
        setTabPermissions(permissions);

        if (!names.includes("Inicio")) {
            setActiveTab(names[0] || "");
        }

        // Reset view to top if simulating
        window.scrollTo(0,0);
    }, [setCongregation]);

    // Handle exiting simulation/logout
    const handleExit = () => {
        localStorage.removeItem('vmt_auto_token'); // Clear persistent token
        sessionStorage.removeItem('vmt_is_super_admin'); // Clear session
        window.location.href = window.location.origin + window.location.pathname; // Hard reload
    };

    useEffect(() => {
        const checkAccess = async () => {
            setIsLoadingAccess(true);

            // Priority: If session says we are Super Admin, trust it and skip token logic
            if (isSuperAdmin) {
                setIsLoadingAccess(false);
                return;
            }

            const urlParams = new URLSearchParams(window.location.search);
            const view = urlParams.get('view');
            const participant = urlParams.get('participant');
            const token = urlParams.get('token');
            const urlCongregationId = urlParams.get('congregation_id');
            const savedAutoToken = localStorage.getItem('vmt_auto_token');

            if (view === 'assignments' && participant) {
                setSpecialView({ view, participant: decodeURIComponent(participant) });
                setIsLoadingAccess(false);
                return;
            }

            // Theme and View Mode logic
            const prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
            setTheme(prefersDark ? 'dark' : 'light');
            const isMobileDevice = () => /Mobi/i.test(window.navigator.userAgent) || window.innerWidth < 1024;
            setViewMode(isMobileDevice() ? 'mobile' : 'desktop');

            // --- 1. DIRECT LINK HANDLING (Token URL) ---
            if (token) {
                try {
                    const { data, error } = await supabase
                        .from('access_configs')
                        .select('access_token, visible_tabs, label, restricted_group_id, congregation_id')
                        .eq('access_token', token)
                        .single();

                    if (data && !error) {
                        await applyAccessConfig(data, true); // Auto-save token from URL
                    }
                } catch (e) {
                    console.error("Error fetching access config", e);
                }
            } 
            // --- 2. AUTO LOGIN (Persistent Token) ---
            else if (savedAutoToken) {
                try {
                    const { data, error } = await supabase
                        .from('access_configs')
                        .select('access_token, visible_tabs, label, restricted_group_id, congregation_id')
                        .eq('access_token', savedAutoToken)
                        .single();

                    if (data && !error) {
                        await applyAccessConfig(data, false);
                    } else {
                        // Token invalid/expired
                        localStorage.removeItem('vmt_auto_token');
                    }
                } catch (e) {
                    console.error("Error with auto-token", e);
                }
            }
            // --- 3. CONGREGATION LINK (No token, public access to ID) ---
            else if (urlCongregationId) {
                const { data: congData } = await supabase
                    .from('congregations')
                    .select('*')
                    .eq('id', parseInt(urlCongregationId))
                    .single();

                if (congData) {
                    setCongregation(congData);
                    // Default admin perms if no token provided in URL
                    const adminPerms = defaultNavItems.map(t => ({ name: t, access: 'edit' as const }));
                    setTabPermissions(adminPerms);
                    // Direct link access is NOT super admin unless they log in
                    setIsSuperAdmin(false);
                }
            }
            // --- 4. DEFAULT ADMIN ---
            else {
                // No token found, user will see selector.
                // We set default perms in case they pick a congregation manually from list
                const adminPerms = defaultNavItems.map(t => ({ name: t, access: 'edit' as const }));
                setTabPermissions(adminPerms);
            }

            setIsLoadingAccess(false);
        };

        checkAccess();
    }, [applyAccessConfig, isSuperAdmin]); // Dependency on isSuperAdmin ensures we react if it changes (e.g. login)

    const toggleTheme = () => setTheme(prevTheme => (prevTheme === 'light' ? 'dark' : 'light'));
    const toggleViewMode = () => setViewMode(prevMode => (prevMode === 'desktop' ? 'mobile' : 'desktop'));

    const isReadOnly = useMemo(() => {
        if (isSuperAdmin) return false; // Super admin always edits
        if (!accessLabel) return false;
        const perm = tabPermissions.find(p => p.name === activeTab);
        return perm ? perm.access === 'view' : true;
    }, [accessLabel, activeTab, tabPermissions, isSuperAdmin]);

    const appClassName = `theme-${theme} view-${viewMode}`;

    if (loading) return <div style={{display:'flex',justifyContent:'center',alignItems:'center',height:'100vh', background:'var(--bg-color)', color:'var(--text-color)'}}>Cargando...</div>;
    if (isLoadingAccess) return <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh', color: '#666' }}>Verificando credenciales...</div>;

    // If no congregation is selected and we are NOT in a specific token view (admin mode without token), show selector
    if (!currentCongregation && !specialView) {
        return <CongregationSelector onTokenSuccess={applyAccessConfig} onSetSuperAdmin={setIsSuperAdmin} />;
    }

    if (specialView?.view === 'assignments') {
        return <div className={`app-container ${appClassName}`}><AcceptAssignments participant={specialView.participant} /></div>;
    }

    return (
        <div className={`app-container ${appClassName}`}>
            <Header
                navItems={navItems}
                activeTab={activeTab}
                setActiveTab={setActiveTab}
                theme={theme}
                toggleTheme={toggleTheme}
                viewMode={viewMode}
                toggleViewMode={toggleViewMode}
                congregationName={currentCongregation?.name}
            />
            {/* Show view banner ONLY if it's a specific token view AND not a Super Admin */}
            {accessLabel && !isSuperAdmin && (
                <div style={{ backgroundColor: 'var(--primary-light)', color: 'var(--primary-color)', padding: '10px', textAlign: 'center', fontSize: '0.9rem', borderBottom: '1px solid var(--border-color)', display:'flex', justifyContent:'center', alignItems:'center', gap:'10px', fontWeight:'600' }}>
                    <span><i className="fas fa-eye mr-2"></i> Vista: {accessLabel}</span>
                    {isReadOnly ? 
                        <span style={{fontSize:'0.75rem', padding:'2px 8px', backgroundColor:'rgba(0,0,0,0.1)', borderRadius:'12px'}}>Solo Lectura</span> : 
                        <span style={{fontSize:'0.75rem', padding:'2px 8px', backgroundColor:'var(--positive-color)', color:'white', borderRadius:'12px'}}>Edición</span>
                    }
                    {restrictedGroupId && (
                        <span style={{fontSize:'0.75rem', padding:'2px 8px', backgroundColor:'var(--secondary-color)', color:'white', borderRadius:'12px'}}><i className="fas fa-lock mr-1"></i>Grupo Restringido</span>
                    )}
                    <button onClick={handleExit} style={{marginLeft:'auto', background:'none', border:'none', cursor:'pointer', color:'var(--destructive-color)', fontWeight:'bold', fontSize:'0.8rem', display:'flex', alignItems:'center', gap:'4px'}}>
                        <i className="fas fa-sign-out-alt"></i> Salir
                    </button>
                </div>
            )}
            {/* Super Admin specific logout bar (discreet) */}
            {isSuperAdmin && (
                <div style={{ backgroundColor: '#1e293b', color: 'white', padding: '5px 10px', textAlign: 'right', fontSize: '0.8rem', display:'flex', justifyContent:'flex-end', alignItems:'center', gap:'10px' }}>
                    <span style={{opacity:0.7}}><i className="fas fa-user-shield mr-1"></i> Administrador Global</span>
                    <button onClick={handleExit} style={{background:'none', border:'none', cursor:'pointer', color:'#fca5a5', fontWeight:'bold', fontSize:'0.8rem'}}>
                        Salir
                    </button>
                </div>
            )}
            <main>
                <div style={{ display: activeTab === 'Inicio' ? 'block' : 'none' }}><Inicio accessLabel={isSuperAdmin ? null : accessLabel} /></div>

                {navItems.includes('Recordatorios') && (
                    <div style={{ display: activeTab === 'Recordatorios' ? 'block' : 'none' }}>
                        <Recordatorios isReadOnly={isReadOnly} />
                    </div>
                )}

                {navItems.includes('Programa') && (
                    <div style={{ display: activeTab === 'Programa' ? 'block' : 'none' }}>
                        <Programa isReadOnly={isReadOnly} />
                    </div>
                )}

                {navItems.includes('Gestionar Participantes') && (
                    <div style={{ display: activeTab === 'Gestionar Participantes' ? 'block' : 'none' }}>
                        <GestionarParticipantes isReadOnly={isReadOnly} /> 
                    </div>
                )}

                {navItems.includes('Grupo de Congregación') && (
                    <div style={{ display: activeTab === 'Grupo de Congregación' ? 'block' : 'none' }}>
                        <GrupoCongregacion isReadOnly={isReadOnly} restrictedGroupId={isSuperAdmin ? null : restrictedGroupId} />
                    </div>
                )}

                {navItems.includes('Filtros Avanzados') && (
                    <div style={{ display: activeTab === 'Filtros Avanzados' ? 'block' : 'none' }}>
                        <FiltrosAvanzados />
                    </div>
                )}

                {navItems.includes('Respuestas de Asignaciones') && (
                    <div style={{ display: activeTab === 'Respuestas de Asignaciones' ? 'block' : 'none' }}>
                        <HistorialEventos />
                    </div>
                )}

                {navItems.includes('Informes') && (
                    <div style={{ display: activeTab === 'Informes' ? 'block' : 'none' }}>
                        <Informes restrictedGroupId={isSuperAdmin ? null : restrictedGroupId} />
                    </div>
                )}

                {navItems.includes('Planificador') && (
                    <div style={{ display: activeTab === 'Planificador' ? 'block' : 'none' }}>
                        <Planificador isReadOnly={isReadOnly} />
                    </div>
                )}

                {navItems.includes('Asignar Anc. y Min.') && (
                    <div style={{ display: activeTab === 'Asignar Anc. y Min.' ? 'block' : 'none' }}>
                        <AsignarAncMin isReadOnly={isReadOnly} />
                    </div>
                )}

                {navItems.includes('Configuración') && (
                    <div style={{ display: activeTab === 'Configuración' ? 'block' : 'none' }}>
                        <ConfiguracionAcceso onSimulate={applyAccessConfig} isSuperAdmin={isSuperAdmin} />
                    </div>
                )}
            </main>
        </div>
    );
};

const App: React.FC = () => {
    return (
        <CongregationProvider>
            <AppContent />
        </CongregationProvider>
    );
};

export default App;

import { useState, useEffect, useCallback } from 'react';
import { supabase } from './supabase';
import { ProgramData, AssignmentHistory, ParticipantLists } from './types';
import { useCongregation } from './CongregationContext';

const managerConfig = [
    { type: 'presidentes', tableName: 'lista_encargados' },
    { type: 'consejeros', tableName: 'consejeros' },
    { type: 'oradores', tableName: 'oradores' },
    { type: 'discursantes', tableName: 'discursantes' },
    { type: 'lectores', tableName: 'lectores' },
    { type: 'lectores_libro', tableName: 'lectores_libro' },
    { type: 'publicadores', tableName: 'publicadores' },
    { type: 'maestros_discurso', tableName: 'maestros_discurso' }
];

// Helper to strip personal assignments but keep structure (themes, songs, times)
const cleanAssignments = (data: any) => {
    if (!data) return {};
    const clean = JSON.parse(JSON.stringify(data));

    // Clear singular assignments
    if (clean.presidentes) {
        clean.presidentes.principal = "";
        clean.presidentes.aux2 = "";
        clean.presidentes.aux3 = "";
    }
    if (clean.oracion) {
        clean.oracion.inicio = "";
        clean.oracion.final = "";
    }

    // Clear Tesoros assignments (keep titles)
    if (clean.tesoros) {
        if (clean.tesoros.p1) clean.tesoros.p1.main = "";
        if (clean.tesoros.p2) clean.tesoros.p2.main = "";
        if (clean.tesoros.p3) {
            clean.tesoros.p3.main = "";
            clean.tesoros.p3.aux2 = "";
            clean.tesoros.p3.aux3 = "";
        }
    }

    // Clear Maestros assignments (keep titles)
    if (clean.maestros && Array.isArray(clean.maestros)) {
        clean.maestros.forEach((m: any) => {
            m.main = "";
            m.aux2 = "";
            m.aux3 = "";
        });
    }

    // Clear Vida Cristiana assignments (keep titles)
    if (clean.vidaCristiana && Array.isArray(clean.vidaCristiana)) {
        clean.vidaCristiana.forEach((v: any) => {
            if (v.hasOwnProperty('conductor')) v.conductor = "";
            if (v.hasOwnProperty('lector')) v.lector = "";
            if (v.hasOwnProperty('discursante')) v.discursante = "";
        });
    }

    return clean;
};

// Helper to merge a base program (structure) with local program (assignments)
const mergePrograms = (baseProgram: any, localProgram: any) => {
    if (!baseProgram) return localProgram;
    if (!localProgram) return baseProgram;

    const merged = JSON.parse(JSON.stringify(localProgram));
    const base = baseProgram.data || {};

    // Ensure data object exists
    if (!merged.data) merged.data = {};

    // Copy structural fields from base if missing in local
    merged.data.titulo = merged.data.titulo || base.titulo;
    merged.data.canciones = { ...base.canciones, ...merged.data.canciones };
    // Merge oracion structure (but base is already cleaned of names in the calling function)
    merged.data.oracion = { ...base.oracion, ...merged.data.oracion }; 
    merged.data.sectionTitles = { ...base.sectionTitles, ...merged.data.sectionTitles };

    // Explicitly preserve config fields (Watermark & Blur)
    // Priority: Local > Base > Default
    merged.data.watermark = merged.data.watermark ?? base.watermark ?? 'PRELIMINAR';
    merged.data.isBlurred = merged.data.isBlurred ?? base.isBlurred ?? false;

    // Merge Tesoros (Structure vs Assignments)
    if (base.tesoros) {
        merged.data.tesoros = merged.data.tesoros || {};
        ['p1', 'p2', 'p3'].forEach(k => {
            if (base.tesoros[k]) {
                merged.data.tesoros[k] = { ...base.tesoros[k], ...merged.data.tesoros[k] };
                // Ensure title comes from base
                if (base.tesoros[k].title) merged.data.tesoros[k].title = base.tesoros[k].title;
            }
        });
    }

    // Merge Maestros (Array matching)
    if (base.maestros && Array.isArray(base.maestros)) {
        merged.data.maestros = merged.data.maestros || [];
        base.maestros.forEach((baseItem: any, index: number) => {
            if (!merged.data.maestros[index]) merged.data.maestros[index] = {};
            // Structure from base, assignments from local
            merged.data.maestros[index].title = baseItem.title;
            merged.data.maestros[index].time = baseItem.time;
        });
    }

    // Merge Vida Cristiana
    if (base.vidaCristiana && Array.isArray(base.vidaCristiana)) {
        merged.data.vidaCristiana = merged.data.vidaCristiana || [];
        base.vidaCristiana.forEach((baseItem: any, index: number) => {
            if (!merged.data.vidaCristiana[index]) merged.data.vidaCristiana[index] = {};
            merged.data.vidaCristiana[index].titulo = baseItem.titulo;
            merged.data.vidaCristiana[index].time = baseItem.time;
            merged.data.vidaCristiana[index].numero = baseItem.numero;
            // Preserves assignment properties (conductor, lector, discursante) if they exist in local
        });
    }

    return merged;
};

const createUnifiedHistory = (programs: any[]): AssignmentHistory => {
    const history: AssignmentHistory = new Map();
    const addHistoryEntry = (name: string | null | undefined, date: string, description: string) => {
        if (!name || name.trim() === '') return;
        const names = name.split('/').map(n => n.trim()).filter(Boolean);
        names.forEach((p, index) => {
            const roleSuffix = names.length > 1 ? (index === 0 ? ' (Enc.)' : ' (Ayu.)') : '';
            if (!history.has(p)) {
                history.set(p, { mostRecent: '0000-00-00', assignments: [] });
            }
            const personHistory = history.get(p)!;
            if (!personHistory.assignments.some(a => a.date === date && a.description === (description + roleSuffix))) {
                personHistory.assignments.push({ date, description: description + roleSuffix });
            }
            if (date > personHistory.mostRecent) {
                personHistory.mostRecent = date;
            }
        });
    };

    programs.forEach(prog => {
        const data = prog.data || {};
        const week_id = prog.week_id;

        addHistoryEntry(data.presidentes?.principal, week_id, "Presidente");
        addHistoryEntry(data.presidentes?.aux2, week_id, "Consejero");
        addHistoryEntry(data.presidentes?.aux3, week_id, "Consejero");
        addHistoryEntry(data.oracion?.inicio, week_id, "Oración Inicio");
        addHistoryEntry(data.oracion?.final, week_id, "Oración Final");
        if(data.tesoros?.p1) addHistoryEntry(data.tesoros.p1.main, week_id, data.tesoros.p1.title);
        if(data.tesoros?.p2) addHistoryEntry(data.tesoros.p2.main, week_id, data.tesoros.p2.title);
        if(data.tesoros?.p3) {
             ['main', 'aux2', 'aux3'].forEach(room => {
                addHistoryEntry(data.tesoros.p3[room], week_id, `Lectura Biblia`);
            });
        }
        (data.maestros || []).forEach((part: any) => {
            const cleanTitle = part.title ? part.title.replace(/\s*\(\d+\s*min(s)?\.?\)/i, '').trim() : `SMM`;
            ['main', 'aux2', 'aux3'].forEach(room => {
                addHistoryEntry(part[room], week_id, cleanTitle);
            });
        });
        (data.vidaCristiana || []).forEach((part: any) => {
            if (part.hasOwnProperty('conductor')) {
                addHistoryEntry(part.conductor, week_id, "Libro de Congregación");
            }
            if (part.hasOwnProperty('lector')) {
                addHistoryEntry(part.lector, week_id, "Lector del Libro");
            }
            if (part.hasOwnProperty('discursante')) {
                if (part.titulo?.toLowerCase().includes('necesidades')) {
                    addHistoryEntry(part.discursante, week_id, "Necesidades de Cong.");
                } else {
                    addHistoryEntry(part.discursante, week_id, "Discurso Vida Cr.");
                }
            }
        });
    });

    for (let personHistory of history.values()) {
        personHistory.assignments.sort((a, b) => b.date.localeCompare(a.date));
    }
    return history;
};


export const useProgramData = () => {
    const { currentCongregation } = useCongregation();
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [data, setData] = useState<ProgramData>({ programs: [], lists: {}, history: new Map() });

    const fetchData = useCallback(async () => {
        if (!currentCongregation) return;
        setLoading(true);
        setError(null);
        try {
            const selectPromises = managerConfig.map(m => 
                supabase.from(m.tableName).select("nombre").eq('congregation_id', currentCongregation.id).order("nombre")
            );

            // 1. Fetch Local Programs (Assignments specifically for this congregation)
            const localProgramPromise = supabase
                .from("programas")
                .select("week_id, data")
                .eq('congregation_id', currentCongregation.id)
                .order("week_id", { ascending: true });

            // 2. Fetch Base Programs (Source of Truth for structure, e.g. from Congregation ID 1)
            const baseProgramPromise = supabase
                .from("programas")
                .select("week_id, data")
                .eq('congregation_id', 1) 
                .order("week_id", { ascending: true });

            // Use Promise.allSettled to handle potential failures in base program fetch
            // This is crucial because if congregation 1 is restricted or network issues occur for one query,
            // we should still try to load what we can.
            const results = await Promise.allSettled([
                localProgramPromise, 
                baseProgramPromise, 
                ...selectPromises
            ]);

            const localRes = results[0].status === 'fulfilled' ? results[0].value : { data: [], error: results[0].reason };
            const baseRes = results[1].status === 'fulfilled' ? results[1].value : { data: [], error: null }; // Treat base error as empty

            if (localRes.error) throw localRes.error;

            const lists: ParticipantLists = {};
            // Selects start from index 2
            results.slice(2).forEach((res, index) => {
                if (res.status === 'fulfilled') {
                    lists[managerConfig[index].type] = res.value.data || [];
                } else {
                    console.warn(`Error loading ${managerConfig[index].type}:`, res.reason);
                    lists[managerConfig[index].type] = [];
                }
            });

            const localPrograms = localRes.data || [];
            const basePrograms = baseRes.data || [];

            // 3. Merge Logic
            const allWeekIds = new Set([...localPrograms.map((p: any) => p.week_id), ...basePrograms.map((p: any) => p.week_id)]);

            const mergedPrograms = Array.from(allWeekIds).map(weekId => {
                const local = localPrograms.find((p: any) => p.week_id === weekId);
                const base = basePrograms.find((p: any) => p.week_id === weekId);

                // CRITICAL: Clean the base data to ensure no assignments from the source congregation leak into this one
                const baseCleanData = base ? cleanAssignments(base.data) : null;
                const baseCleanProgram = base ? { ...base, data: baseCleanData } : null;

                if (local && baseCleanProgram) {
                    // Have both: merge clean structure from base into local assignments
                    return { week_id: weekId, data: mergePrograms(baseCleanProgram, local).data };
                } else if (local) {
                    // Only local exists
                    return local;
                } else {
                    // Only base exists: use clean structure with empty assignments
                    return JSON.parse(JSON.stringify(baseCleanProgram)); 
                }
            }).sort((a,b) => a.week_id.localeCompare(b.week_id));

            const history = createUnifiedHistory(mergedPrograms);

            setData({ programs: mergedPrograms, lists, history });

        } catch (err: any) {
            console.error("useProgramData Error:", err);
            setError(err.message);
        } finally {
            setLoading(false);
        }
    }, [currentCongregation]);

    useEffect(() => {
        fetchData();
    }, [fetchData]);

    return { ...data, loading, error, refetch: fetchData };
};

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { useCongregation } from '../lib/CongregationContext';

// Pestañas disponibles en el sistema
export const ALL_TABS = [
    "Inicio",
    "Recordatorios",
    "Programa",
    "Gestionar Participantes",
    "Grupo de Congregación",
    "Filtros Avanzados",
    "Respuestas de Asignaciones",
    "Informes",
    "Planificador",
    "Asignar Anc. y Min."
];

type TabPermission = {
    name: string;
    access: 'view' | 'edit';
};

type AccessConfig = {
    id: string;
    label: string;
    responsible_name: string;
    visible_tabs: TabPermission[];
    access_token: string;
    restricted_group_id?: number | null;
    created_at: string;
    congregation_id?: number;
};

interface ConfiguracionAccesoProps {
    onSimulate?: (config: any) => void;
    isSuperAdmin?: boolean;
}

const ConfiguracionAcceso: React.FC<ConfiguracionAccesoProps> = ({ onSimulate, isSuperAdmin = false }) => {
    const { currentCongregation, refreshCongregations } = useCongregation();
    const [configs, setConfigs] = useState<AccessConfig[]>([]);
    const [groups, setGroups] = useState<{id: number, nombre: string}[]>([]);
    const [loading, setLoading] = useState(true);
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    // Configuración General (Salas)
    const [enabledRooms, setEnabledRooms] = useState({ main: true, aux2: true, aux3: true });
    const [loadingSettings, setLoadingSettings] = useState(false);

    // Estado del Formulario
    const [label, setLabel] = useState('');
    const [responsible, setResponsible] = useState('');
    const [password, setPassword] = useState(''); // New State for Password
    const [restrictedGroupId, setRestrictedGroupId] = useState<string>('');
    const [selectedTabs, setSelectedTabs] = useState<TabPermission[]>([
        { name: "Inicio", access: "view" },
        { name: "Programa", access: "view" }
    ]);
    const [editingId, setEditingId] = useState<string | null>(null);

    useEffect(() => {
        if (currentCongregation) {
            fetchConfigs();
            fetchGroups();
            if (currentCongregation.settings?.enabled_rooms) {
                setEnabledRooms(currentCongregation.settings.enabled_rooms);
            }
        }
    }, [currentCongregation]);

    const fetchGroups = async () => {
        if (!currentCongregation) return;
        const { data } = await supabase.from('grupos')
            .select('id, nombre')
            .eq('congregation_id', currentCongregation.id)
            .order('nombre');
        if (data) setGroups(data);
    };

    const fetchConfigs = async () => {
        if (!currentCongregation) return;
        setLoading(true);
        const { data, error } = await supabase.from('access_configs')
            .select('*')
            .eq('congregation_id', currentCongregation.id)
            .order('created_at', { ascending: false });

        if (!error) {
            // Normalizar datos antiguos si existen
            const normalizedData = (data || []).map(config => ({
                ...config,
                visible_tabs: Array.isArray(config.visible_tabs) 
                    ? config.visible_tabs.map((t: any) => typeof t === 'string' ? { name: t, access: 'view' } : t)
                    : []
            }));
            setConfigs(normalizedData);
        }
        setLoading(false);
    };

    const handleSaveAccess = async () => {
        if (!currentCongregation) return;
        if (!label.trim() || !responsible.trim() || !password.trim() || selectedTabs.length === 0) {
            setStatusMessage({ text: 'Faltan campos obligatorios (Nombre, Responsable, Contraseña, Permisos)', type: 'error' });
            return;
        }

        // Basic duplicate check for password within this congregation
        const duplicate = configs.find(c => c.access_token === password.trim() && c.id !== editingId);
        if (duplicate) {
            setStatusMessage({ text: 'Esta contraseña ya está en uso por otro usuario.', type: 'error' });
            return;
        }

        const payload = {
            label: label.trim(),
            responsible_name: responsible.trim(),
            access_token: password.trim(), // Use manual password
            visible_tabs: selectedTabs,
            restricted_group_id: restrictedGroupId ? parseInt(restrictedGroupId) : null,
            congregation_id: currentCongregation.id
        };

        let error;
        if (editingId) {
            const { error: updateError } = await supabase.from('access_configs').update(payload).eq('id', editingId);
            error = updateError;
        } else {
            const { error: insertError } = await supabase.from('access_configs').insert([payload]);
            error = insertError;
        }

        if (error) {
            setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
        } else {
            setStatusMessage({ text: 'Configuración guardada correctamente', type: 'success' });
            resetForm();
            fetchConfigs();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const toggleTab = (tabName: string) => {
        setSelectedTabs(prev => {
            const index = prev.findIndex(t => t.name === tabName);
            if (index === -1) {
                // No está, añadir como vista
                return [...prev, { name: tabName, access: 'view' }];
            } else if (prev[index].access === 'view') {
                // Está como vista, cambiar a edición
                const newTabs = [...prev];
                newTabs[index] = { ...newTabs[index], access: 'edit' };
                return newTabs;
            } else {
                // Está como edición, quitar
                return prev.filter(t => t.name !== tabName);
            }
        });
    };

    const resetForm = () => {
        setLabel('');
        setResponsible('');
        setPassword('');
        setRestrictedGroupId('');
        setSelectedTabs([{ name: "Inicio", access: "view" }, { name: "Programa", access: "view" }]);
        setEditingId(null);
    };

    const handleEditClick = (config: AccessConfig) => {
        setEditingId(config.id);
        setLabel(config.label);
        setResponsible(config.responsible_name);
        setPassword(config.access_token);
        setSelectedTabs(config.visible_tabs);
        setRestrictedGroupId(config.restricted_group_id ? String(config.restricted_group_id) : '');
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    const handleDelete = async (id: string) => {
        if (!window.confirm('¿Eliminar este acceso?')) return;
        const { error } = await supabase.from('access_configs').delete().eq('id', id);
        if (!error) fetchConfigs();
    };

    const saveGeneralSettings = async () => {
        if (!currentCongregation) return;
        setLoadingSettings(true);
        const { error } = await supabase.from('congregations')
            .update({ settings: { ...currentCongregation.settings, enabled_rooms: enabledRooms } })
            .eq('id', currentCongregation.id);

        if (!error) {
            setStatusMessage({ text: 'Configuración de salas guardada', type: 'success' });
            await refreshCongregations();
        }
        setLoadingSettings(false);
        setTimeout(() => setStatusMessage(null), 3000);
    };

    return (
        <div className="container mx-auto px-4 py-8">
            <h1 className="page-title"><i className="fas fa-user-shield mr-2"></i>Panel de Administración</h1>

            {/* Configuración de Salas */}
            <div style={{ backgroundColor: 'var(--card-bg-color)', padding: '24px', borderRadius: '16px', border: '1px solid var(--border-color)', marginBottom: '30px', boxShadow: 'var(--shadow-md)' }}>
                <h3 style={{ marginTop: 0, marginBottom: '20px', color: 'var(--primary-color)', fontSize: '1.2rem', fontWeight: '800' }}>
                    <i className="fas fa-door-open mr-2"></i>Salas Activas de la Congregación
                </h3>
                <div style={{ display: 'flex', gap: '20px', flexWrap: 'wrap', marginBottom: '20px' }}>
                    {Object.entries({ main: "Auditorio Principal", aux2: "Sala 2", aux3: "Sala 3" }).map(([key, label]) => (
                        <label key={key} style={{ display: 'flex', alignItems: 'center', gap: '10px', cursor: 'pointer', fontSize: '1rem', fontWeight: '600' }}>
                            <input 
                                type="checkbox" 
                                checked={enabledRooms[key as keyof typeof enabledRooms]} 
                                onChange={e => setEnabledRooms(prev => ({ ...prev, [key]: e.target.checked }))}
                                disabled={key === 'main'}
                                style={{ width: '20px', height: '20px', accentColor: 'var(--primary-color)' }}
                            />
                            {label}
                        </label>
                    ))}
                </div>
                <button onClick={saveGeneralSettings} disabled={loadingSettings} className="button-save" style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                    {loadingSettings ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-save"></i>}
                    Guardar Configuración de Salas
                </button>
            </div>

            {/* Formulario de Llaves/Contraseñas */}
            <div style={{ backgroundColor: 'var(--card-bg-color)', padding: '24px', borderRadius: '16px', border: editingId ? '2px solid var(--primary-color)' : '1px solid var(--border-color)', marginBottom: '30px', boxShadow: 'var(--shadow-lg)' }}>
                <h3 style={{ marginTop: 0, marginBottom: '20px', color: 'var(--primary-color)', fontSize: '1.2rem', fontWeight: '800' }}>
                    {editingId ? <><i className="fas fa-edit mr-2"></i>Editar Acceso</> : <><i className="fas fa-key mr-2"></i>Crear Nuevo Acceso</>}
                </h3>

                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '20px', marginBottom: '25px' }}>
                    <div>
                        <label style={{ display: 'block', fontWeight: '700', marginBottom: '8px', fontSize: '0.85rem', color: 'var(--text-color-light)', textTransform: 'uppercase' }}>Nombre del Perfil</label>
                        <input type="text" value={label} onChange={e => setLabel(e.target.value)} placeholder="Ej: Grupo 1, Ancianos, etc." />
                    </div>
                    <div>
                        <label style={{ display: 'block', fontWeight: '700', marginBottom: '8px', fontSize: '0.85rem', color: 'var(--text-color-light)', textTransform: 'uppercase' }}>Nombre del Responsable</label>
                        <input type="text" value={responsible} onChange={e => setResponsible(e.target.value)} placeholder="Ej: Hno. Pérez" />
                    </div>
                    <div>
                        <label style={{ display: 'block', fontWeight: '700', marginBottom: '8px', fontSize: '0.85rem', color: 'var(--text-color-light)', textTransform: 'uppercase' }}>Contraseña de Acceso</label>
                        <input 
                            type="text" 
                            value={password} 
                            onChange={e => setPassword(e.target.value)} 
                            placeholder="Ej: 123456" 
                            style={{ fontFamily: 'monospace', letterSpacing: '1px', fontWeight: 'bold' }}
                        />
                    </div>
                    <div>
                        <label style={{ display: 'block', fontWeight: '700', marginBottom: '8px', fontSize: '0.85rem', color: 'var(--text-color-light)', textTransform: 'uppercase' }}>Restringir a Grupo (Opcional)</label>
                        <select value={restrictedGroupId} onChange={e => setRestrictedGroupId(e.target.value)}>
                            <option value="">-- Sin restricción (Todos) --</option>
                            {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                        </select>
                    </div>
                </div>

                <div style={{ marginBottom: '25px' }}>
                    <label style={{ display: 'block', fontWeight: '700', marginBottom: '12px', fontSize: '0.85rem', color: 'var(--text-color-light)', textTransform: 'uppercase' }}>
                        Permisos de Pestañas (Clic para alternar: <i className="fas fa-eye text-blue-500"></i> Solo Ver → <i className="fas fa-edit text-green-500"></i> Edición → Desactivar)
                    </label>
                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
                        {ALL_TABS.map(tab => {
                            const perm = selectedTabs.find(t => t.name === tab);
                            const isActive = !!perm;
                            const isEdit = perm?.access === 'edit';

                            return (
                                <button
                                    key={tab}
                                    onClick={() => toggleTab(tab)}
                                    style={{
                                        padding: '8px 16px',
                                        borderRadius: '30px',
                                        border: isActive ? (isEdit ? '2px solid #10b981' : '2px solid #3b82f6') : '1px solid var(--border-color)',
                                        backgroundColor: isActive ? (isEdit ? '#dcfce7' : '#dbeafe') : 'transparent',
                                        color: isActive ? (isEdit ? '#065f46' : '#1e40af') : 'var(--text-color-light)',
                                        fontWeight: isActive ? '800' : '500',
                                        cursor: 'pointer',
                                        display: 'flex',
                                        alignItems: 'center',
                                        gap: '6px',
                                        transition: 'all 0.2s'
                                    }}
                                >
                                    {isActive && <i className={`fas ${isEdit ? 'fa-edit' : 'fa-eye'}`}></i>}
                                    <span>{tab}</span>
                                </button>
                            );
                        })}
                    </div>
                </div>

                <div style={{ display: 'flex', gap: '12px' }}>
                    <button onClick={handleSaveAccess} className="button-save" style={{ flex: 1, padding: '15px' }}>
                        <i className={`fas ${editingId ? 'fa-save' : 'fa-plus'} mr-2`}></i>
                        {editingId ? 'Guardar Cambios' : 'Crear Acceso'}
                    </button>
                    {editingId && <button onClick={resetForm} className="button" style={{ background: '#64748b', color: 'white' }}>Cancelar</button>}
                </div>
            </div>

            {/* Listado de Llaves */}
            <h2 style={{ fontSize: '1.4rem', fontWeight: '800', marginBottom: '20px', display: 'flex', alignItems: 'center', gap: '10px' }}>
                <i className="fas fa-users-cog color-primary"></i>Accesos Generados
            </h2>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: '20px' }}>
                {loading ? <p>Cargando...</p> : configs.map(config => (
                    <div key={config.id} style={{ backgroundColor: 'var(--card-bg-color)', borderRadius: '16px', padding: '20px', border: '1px solid var(--border-color)', boxShadow: 'var(--shadow-md)', position: 'relative', display: 'flex', flexDirection: 'column' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '15px' }}>
                            <div style={{ flex: 1 }}>
                                <h3 style={{ margin: 0, fontSize: '1.1rem', fontWeight: '800', color: 'var(--text-color)' }}>{config.label}</h3>
                                <p style={{ margin: '4px 0 0 0', fontSize: '0.9rem', color: 'var(--text-color-light)', fontWeight: '600' }}>
                                    <i className="fas fa-user-circle mr-1"></i>{config.responsible_name}
                                </p>
                            </div>
