const Informes: React.FC<InformesProps> = ({ restrictedGroupId }) => {
    const { currentCongregation } = useCongregation();
    const [fullDataCache, setFullDataCache] = useState<any>({});
    const [allAssignments, setAllAssignments] = useState<Assignment[]>([]);
    const [filteredAssignments, setFilteredAssignments] = useState<Assignment[]>([]);
    const [allowedParticipants, setAllowedParticipants] = useState<Set<string> | null>(null);

    // Filters
    const [startWeek, setStartWeek] = useState('');
    const [endWeek, setEndWeek] = useState('');
    const [person, setPerson] = useState('');
    const [assignmentType, setAssignmentType] = useState('');
    const [showFilters, setShowFilters] = useState(false); // Mobile filter toggle

    const [weekOptions, setWeekOptions] = useState<string[]>([]);
    const [personOptions, setPersonOptions] = useState<string[]>([]);
    const [assignmentOptions, setAssignmentOptions] = useState<string[]>([]);

    const [loadingSlipId, setLoadingSlipId] = useState<string | null>(null);
    const [filesToShare, setFilesToShare] = useState<{ [slipId: string]: File }>({});
    const [isDownloadingPdf, setIsDownloadingPdf] = useState(false);

    // Fetch allowed members if restriction is active
    useEffect(() => {
        const fetchRestrictedMembers = async () => {
            if (restrictedGroupId) {
                const { data } = await supabase
                    .from('miembros_grupo')
                    .select('publicador_nombre')
                    .eq('grupo_id', restrictedGroupId);

                if (data) {
                    const membersSet = new Set<string>(data.map((m: any) => m.publicador_nombre));
                    setAllowedParticipants(membersSet);
                }
            } else {
                setAllowedParticipants(null);
            }
        };
        fetchRestrictedMembers();
    }, [restrictedGroupId]);

    const processData = useCallback(() => {
        const assignments: Assignment[] = [];
        const participantSet = new Set<string>();
        const interventionSet = new Set<string>();

        const isAllowed = (name: string) => {
            if (!allowedParticipants) return true;
            return allowedParticipants.has(name);
        };

        Object.keys(fullDataCache).forEach(weekId => {
            const weekData = fullDataCache[weekId];
            if (!weekData) return;

            // Process Bible Reading
            if (weekData.tesoros?.p3) {
                ["main", "aux2", "aux3"].forEach(room => {
                    if (weekData.tesoros.p3[room]) {
                        const reader = weekData.tesoros.p3[room].trim();
                        if (reader && isAllowed(reader)) {
                            assignments.push({ participant: reader, helper: "", weekId, weekTitle: weekData.titulo, partTitle: "Lectura de la Biblia (3 min.)", room, intendedFor: "participant" });
                            participantSet.add(reader);
                            interventionSet.add("Lectura de la Biblia (3 min.)");
                        }
                    }
                });
            }

            // Process teaching assignments
            (weekData.maestros || []).forEach((assignment: any) => {
                ["main", "aux2", "aux3"].forEach(room => {
                    if (assignment[room]) {
                        const [participant, helper] = assignment[room].split("/").map((name: string) => name.trim()).filter(Boolean);

                        if(participant && isAllowed(participant)) {
                            interventionSet.add(assignment.title);
                            assignments.push({ participant, helper: helper || "", weekId, weekTitle: weekData.titulo, partTitle: assignment.title, room, intendedFor: "participant" });
                            participantSet.add(participant);
                        }

                        if(helper && isAllowed(helper)) {
                            interventionSet.add(assignment.title);
                            assignments.push({ participant, helper, weekId, weekTitle: weekData.titulo, partTitle: assignment.title, room, intendedFor: "helper" });
                            participantSet.add(helper);
                        }
                    }
                });
            });
        });

        setAllAssignments(assignments);

        const today = new Date();
        today.setHours(0,0,0,0);
        const filteredWeeks = Object.keys(fullDataCache)
            .filter(weekId => new Date(weekId) >= today)
            .sort();

        setWeekOptions(filteredWeeks);
        setPersonOptions(Array.from(participantSet).sort());
        setAssignmentOptions(Array.from(interventionSet).sort());

    }, [fullDataCache, allowedParticipants]);

    useEffect(() => {
        const fetchData = async () => {
            if (!currentCongregation) return;

            const { data, error } = await supabase
                .from("programas")
                .select("week_id, data")
                .eq("congregation_id", currentCongregation.id)
                .order("week_id", { ascending: true });

            if (error) {
                console.error("Error fetching data", error);
                return;
            }
            const cache: any = {};
            (data || []).forEach(p => { cache[p.week_id] = p.data; });
            setFullDataCache(cache);
        };
        fetchData();
    }, [currentCongregation]);

    useEffect(() => {
        if (Object.keys(fullDataCache).length > 0) {
            processData();
        }
    }, [fullDataCache, processData]);

    useEffect(() => {
        let filtered = allAssignments;

        // Default to filtering from the first available future week if no start date is selected.
        const effectiveStartWeek = startWeek || (weekOptions[0] || '');

        if (effectiveStartWeek) {
            filtered = filtered.filter(a => a.weekId >= effectiveStartWeek);
        }

        if(endWeek) filtered = filtered.filter(a => a.weekId <= endWeek);
        if(person) filtered = filtered.filter(a => a.participant === person || a.helper === person);
        if(assignmentType) filtered = filtered.filter(a => a.partTitle === assignmentType);
        setFilteredAssignments(filtered);
    }, [startWeek, endWeek, person, assignmentType, allAssignments, weekOptions]);

    const handleShare = async (slipId: string) => {
        if (!navigator.share) {
            alert('La función de compartir no está disponible en este navegador.');
            return;
        }

        if (filesToShare[slipId]) {
            try {
                if (navigator.canShare && navigator.canShare({ files: [filesToShare[slipId]] })) {
                    await navigator.share({
                        files: [filesToShare[slipId]],
                        title: 'Asignación VMT',
                        text: 'Aquí está tu asignación para la reunión.'
                    });
                } else {
                    alert('Este navegador no soporta el compartir archivos.');
                }
            } catch (error) {
                // Ignore abort errors
            }
            return;
        }

        setLoadingSlipId(slipId);

        try {
            const element = document.querySelector(`.report-slip[data-slip-id="${slipId}"]`) as HTMLElement;
            if (!element || typeof html2canvas !== 'function') {
                throw new Error('No se pudo encontrar el elemento para compartir o la librería de captura no está cargada.');
            }

            const elementToCapture = element.cloneNode(true) as HTMLElement;
            const shareButton = elementToCapture.querySelector('.share-button');
            if (shareButton) shareButton.remove();

            elementToCapture.style.position = 'absolute';
            elementToCapture.style.left = '-9999px';
            elementToCapture.style.top = '0px';
            elementToCapture.style.width = `${element.offsetWidth}px`;
            document.body.appendChild(elementToCapture);

            const canvas = await html2canvas(elementToCapture, { useCORS: true, scale: 2 });
            const blob = await new Promise<Blob | null>(resolve => canvas.toBlob(resolve, 'image/png'));
            document.body.removeChild(elementToCapture);

            if (!blob) {
                throw new Error('No se pudo generar la imagen a partir del canvas.');
            }

            const file = new File([blob], 'asignacion.png', { type: 'image/png' });
            setFilesToShare(prev => ({ ...prev, [slipId]: file }));

        } catch (error) {
            console.error("Error al generar imagen:", error);
            alert('Ocurrió un error al generar la imagen para compartir.');
        } finally {
            setLoadingSlipId(null);
        }
    };

    const handleClearFilters = () => {
        setStartWeek('');
        setEndWeek('');
        setPerson('');
        setAssignmentType('');
    };

    const handlePrint = () => {
        const printWindow = window.open('', '_blank');
        if (!printWindow) {
            alert('Por favor, permita las ventanas emergentes para imprimir.');
            return;
        }

        const slipsPerPage = 8;
        const pages = [];
        for (let i = 0; i < filteredAssignments.length; i += slipsPerPage) {
            const chunk = filteredAssignments.slice(i, i + slipsPerPage);
            const pageSlipsHTML = chunk.map(createPrintSlipHTML).join('');
            pages.push(`<div class="print-page">${pageSlipsHTML}</div>`);
        }
        const allPagesHTML = pages.join('');

        printWindow.document.write(`
            <!DOCTYPE html><html lang="es">
            <head><title>Imprimir Asignaciones (S-89)</title><style>${printStyles}</style></head>
            <body>${allPagesHTML}</body></html>`);
        printWindow.document.close();
        printWindow.focus();
        setTimeout(() => {
            printWindow.print();
            printWindow.close();
        }, 250);
    };

    const handleDownloadPdf = () => {
        if (typeof html2pdf === 'undefined') {
            alert('La función de descarga no está disponible. Por favor, recargue la página.');
            return;
        }
        setIsDownloadingPdf(true);

        const slipsPerPage = 8;
        const pages = [];
        for (let i = 0; i < filteredAssignments.length; i += slipsPerPage) {
            const chunk = filteredAssignments.slice(i, i + slipsPerPage);
            const pageSlipsHTML = chunk.map(createPrintSlipHTML).join('');
            pages.push(`<div class="print-page">${pageSlipsHTML}</div>`);
        }
        const allPagesHTML = pages.join('');

        const container = document.createElement('div');
        container.style.position = 'absolute';
        container.style.left = '-9999px';
        container.style.width = '29.7cm'; // A4 landscape width

        const styleElement = document.createElement('style');
        styleElement.innerHTML = printStyles;

        const content = document.createElement('div');
        content.innerHTML = allPagesHTML;

        container.appendChild(styleElement);
        container.appendChild(content);
        document.body.appendChild(container);

        const opt = {
            margin: [0.5, 0.5, 0.5, 0.5], // top, left, bottom, right in cm
            filename: 'asignaciones_vmt.pdf',
            image: { type: 'jpeg', quality: 0.98 },
            html2canvas: { scale: 2, useCORS: true },
            jsPDF: { unit: 'cm', format: 'a4', orientation: 'landscape' }
        };

        html2pdf().from(content).set(opt).save().then(() => {
            setIsDownloadingPdf(false);
            document.body.removeChild(container);
        }).catch((err: any) => {
            console.error("PDF generation failed:", err);
            alert('Ocurrió un error al generar el PDF.');
            setIsDownloadingPdf(false);
            document.body.removeChild(container);
        });
    };


    return (
        <div id="reports-container" className="container mx-auto px-4 py-8">
            <h2 className="page-title">
                Generador de Hojas S-89
                {restrictedGroupId && <span style={{fontSize:'0.5em', verticalAlign:'middle', backgroundColor:'#ef4444', color:'white', padding:'2px 6px', borderRadius:'4px', marginLeft:'8px'}}>Grupo Restringido</span>}
            </h2>

            {/* Mobile Filter Toggle */}
            <div className="md:hidden mb-4">
                <button 
                    onClick={() => setShowFilters(!showFilters)}
                    className="mobile-filters-toggle-btn"
                >
                    <i className={`fas fa-${showFilters ? 'times' : 'filter'} mr-2`}></i>
                    {showFilters ? 'Ocultar Filtros' : 'Filtrar Asignaciones'}
                </button>
            </div>

            <div className={`reports-filters ${showFilters ? 'active' : ''}`}>
                <div className="filter-grid">
                    <div className="filter-item">
                        <label htmlFor="report-week-start">Desde:</label>
                        <select id="report-week-start" value={startWeek} onChange={e => setStartWeek(e.target.value)}>
                            <option value="">-- Inicio --</option>
                            {weekOptions.map(w => <option key={w} value={w}>{fullDataCache[w]?.titulo || w}</option>)}
                        </select>
                    </div>
                    <div className="filter-item">
                        <label htmlFor="report-week-end">Hasta:</label>
                        <select id="report-week-end" value={endWeek} onChange={e => setEndWeek(e.target.value)}>
                             <option value="">-- Fin --</option>
                            {weekOptions.filter(w => w >= startWeek).map(w => <option key={w} value={w}>{fullDataCache[w]?.titulo || w}</option>)}
                        </select>
                    </div>
                    <div className="filter-item">
                        <label htmlFor="report-person-filter">Seleccionar participante:</label>
                        <select id="report-person-filter" value={person} onChange={e => setPerson(e.target.value)}>
                            <option value="">-- {allowedParticipants ? 'Participantes del Grupo' : 'Todos los participantes'} --</option>
                            {personOptions.map(p => <option key={p} value={p}>{p}</option>)}
                        </select>
                    </div>
                    <div className="filter-item">
                        <label htmlFor="report-assignment-filter">Tipo de asignación:</label>
                        <select id="report-assignment-filter" value={assignmentType} onChange={e => setAssignmentType(e.target.value)}>
                           <option value="">-- Todas las asignaciones --</option>
                           {assignmentOptions.map(a => <option key={a} value={a}>{a}</option>)}
                        </select>
                    </div>
                </div>
                <div className="filter-actions">
                    <button onClick={handleClearFilters} className="btn-clear-filters">Limpiar</button>
                    <div className="action-buttons-group">
                        <button onClick={handlePrint} className="button-print"><i className="fas fa-print"></i></button>
                        <button onClick={handleDownloadPdf} className="download-button" disabled={isDownloadingPdf}>
                            {isDownloadingPdf ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-file-pdf"></i>}
                        </button>
                    </div>
                </div>
            </div>

            <p className="filter-note">
                <i className="fas fa-info-circle mr-1"></i> Se muestran asignaciones desde esta semana en adelante.
            </p>

            <div id="reports-output">
                {filteredAssignments.map((a, i) => {
                     const slipId = `slip-${a.weekId}-${i}`;
                     return (
                         <div key={slipId} data-slip-id={slipId} className="report-slip">
                            <h3>ASIGNACIÓN S-89</h3>

                            <div className="slip-main-content">
                                <div className="report-field highlight">
                                    <span className="label-text">Nombre:</span> 
                                    <span className="value-text">{a.participant}</span>
                                    {a.intendedFor === 'participant' && (
                                        <i className="fas fa-check-circle text-green-500 ml-2"></i>
                                    )}
                                </div>
                                <div className="report-field">
                                    <span className="label-text">Ayudante:</span> 
                                    <span className="value-text">{a.helper || 'Ninguno'}</span>
                                    {a.intendedFor === 'helper' && a.helper && (
                                         <i className="fas fa-check-circle text-green-500 ml-2"></i>
                                    )}
                                </div>
                                <div className="report-field">
                                    <span className="label-text">Fecha:</span> 
                                    <span className="value-text date-value">{getFridayFromWeekId(a.weekId, 'long')}</span>
                                </div>
                                <div className="report-field full-width">
                                    <span className="label-text">Intervención:</span> 
                                    <span className="value-text part-title">{a.partTitle}</span>
                                </div>
                            </div>

                            <div className="rooms">
                                <label className={`room-pill ${a.room === 'main' ? 'active' : ''}`}>
                                    <i className="fas fa-users"></i> Principal
                                </label>
                                <label className={`room-pill ${a.room === 'aux2' ? 'active' : ''}`}>
                                    <i className="fas fa-chalkboard-teacher"></i> Sala 2
                                </label>
                                <label className={`room-pill ${a.room === 'aux3' ? 'active' : ''}`}>
                                    <i className="fas fa-chalkboard-teacher"></i> Sala 3
                                </label>
                            </div>

                            <div className="footer-note">
                                <p>S-89-S 11/23</p>
                            </div>

                            <button onClick={() => handleShare(slipId)} className="share-button" disabled={loadingSlipId === slipId}>
                                {loadingSlipId === slipId
                                    ? <i className="fas fa-spinner fa-spin"></i>
                                    : filesToShare[slipId]
                                        ? <i className="fas fa-paper-plane"></i>
                                        : <i className="fab fa-whatsapp"></i>
                                }
                                <span>{filesToShare[slipId] ? 'Enviar' : 'Compartir'}</span>
                            </button>
                        </div>
                     )
                })}
            </div>
        </div>
    );
};

export default Informes;

import React, { useState, useEffect, useMemo } from 'react';
import { supabase } from '../lib/supabase';
import { getFridayFromWeekId } from '../lib/utils';
import { useCongregation } from '../lib/CongregationContext';

declare const html2pdf: any;

type AssignmentStatus = 'pending' | 'accepted' | 'rejected';
type Assignment = { date: string; room: string; subRole: string | null; status: AssignmentStatus; partner: string | null; };
type PersonAssignment = { date: string; room: string; subRole: string | null; role: string; status: AssignmentStatus; partner: string | null; };
type AssignmentsByRole = { [role: string]: { [person: string]: Assignment[] } };
type AssignmentsByPerson = { [person: string]: PersonAssignment[] };

const getDeepValue = (obj: any, path: string) => {
    if (!path) return undefined;
    return path.split('.').reduce((o, key) => (o && o[key] !== undefined) ? o[key] : undefined, obj);
}

const FiltrosAvanzados: React.FC = () => {
    const { currentCongregation } = useCongregation();
    const [assignmentsByRole, setAssignmentsByRole] = useState<AssignmentsByRole>({});
    const [assignmentsByPerson, setAssignmentsByPerson] = useState<AssignmentsByPerson>({});
    const [allParticipants, setAllParticipants] = useState<string[]>([]);

    // Search State
    const [searchTerm, setSearchTerm] = useState<string>('');

    const [loading, setLoading] = useState(true);
    const [isDownloading, setIsDownloading] = useState(false);

    // Calculate current week Monday for filtering
    const currentWeekStart = useMemo(() => {
        const now = new Date();
        const day = now.getDay();
        const diff = now.getDate() - day + (day === 0 ? -6 : 1); // Adjust when day is sunday
        const monday = new Date(now.setDate(diff));
        return monday.toISOString().split('T')[0];
    }, []);

    useEffect(() => {
        const fetchAndProcessData = async () => {
            if (!currentCongregation) return;
            setLoading(true);

            const { data: programs, error } = await supabase
                .from("programas")
                .select("week_id, data")
                .eq('congregation_id', currentCongregation.id)
                .order("week_id", { ascending: true });

            const { data: publishers } = await supabase
                .from("publicadores")
                .select("nombre")
                .eq('congregation_id', currentCongregation.id);

            if (error || !programs) {
                console.error("Error fetching programs", error);
                setLoading(false);
                return;
            }

            const collectedAssignmentsByRole: AssignmentsByRole = {};
            const addAssignment = (role: string, person: string | null | undefined, week_id: string, room: string, jsonPath: string, programData: any) => {
                if (!person || !person.trim()) return;
                const people = person.split("/").map(p => p.trim()).filter(Boolean);

                people.forEach((p, index) => {
                    const subRole = people.length > 1 ? (index === 0 ? "E" : "A") : null;
                    const partner = people.length > 1 ? people[1 - index] : null;

                    let status: AssignmentStatus = 'pending';
                    const statusPath = jsonPath + '_status';
                    const statusObj = getDeepValue(programData, statusPath);
                    if (statusObj && statusObj[p]) {
                        status = statusObj[p];
                    }

                    if (!collectedAssignmentsByRole[role]) collectedAssignmentsByRole[role] = {};
                    if (!collectedAssignmentsByRole[role][p]) collectedAssignmentsByRole[role][p] = [];
                    if (!collectedAssignmentsByRole[role][p].some(a => a.date === week_id && a.room === room)) {
                        collectedAssignmentsByRole[role][p].push({ date: week_id, room, subRole, status, partner });
                    }
                });
            };

            programs.forEach(prog => {
                const { week_id, data } = prog;
                if (!data) return;

                addAssignment("Presidente", data.presidentes?.principal, week_id, "main", "presidentes.principal", data);
                addAssignment("Consejero", data.presidentes?.aux2, week_id, "aux2", "presidentes.aux2", data);
                addAssignment("Consejero", data.presidentes?.aux3, week_id, "aux3", "presidentes.aux3", data);
                addAssignment("Oración Inicio", data.oracion?.inicio, week_id, "main", "oracion.inicio", data);
                addAssignment("Oración Final", data.oracion?.final, week_id, "main", "oracion.final", data);
                addAssignment("Discurso (Tesoros)", data.tesoros?.p1?.main, week_id, "main", "tesoros.p1.main", data);
                addAssignment("Perlas Escondidas", data.tesoros?.p2?.main, week_id, "main", "tesoros.p2.main", data);
                addAssignment("Lectura de la Biblia", data.tesoros?.p3?.main, week_id, "main", "tesoros.p3.main", data);
                addAssignment("Lectura de la Biblia", data.tesoros?.p3?.aux2, week_id, "aux2", "tesoros.p3.aux2", data);
                addAssignment("Lectura de la Biblia", data.tesoros?.p3?.aux3, week_id, "aux3", "tesoros.p3.aux3", data);
                (data.maestros || []).forEach((m: any, i: number) => {
                    const role = (m.title || '').toLowerCase().includes("discurso") ? "Discurso (Maestros)" : "Demostración (Maestros)";
                    addAssignment(role, m.main, week_id, "main", `maestros.${i}.main`, data);
                    addAssignment(role, m.aux2, week_id, "aux2", `maestros.${i}.aux2`, data);
                    addAssignment(role, m.aux3, week_id, "aux3", `maestros.${i}.aux3`, data);
                });
                (data.vidaCristiana || []).forEach((vc: any, i: number) => {
                    if (vc.hasOwnProperty("conductor")) {
                        addAssignment("Libro de Congregación", vc.conductor, week_id, "main", `vidaCristiana.${i}.conductor`, data);
                        if (vc.lector) {
                            addAssignment("Lector del Libro", vc.lector, week_id, "main", `vidaCristiana.${i}.lector`, data);
                        }
                    }
                    if (vc.hasOwnProperty("discursante")) {
                        if ((vc.titulo || '').toLowerCase().includes('necesidades')) {
                            addAssignment("Necesidades de Cong.", vc.discursante, week_id, "main", `vidaCristiana.${i}.discursante`, data);
                        } else {
                            addAssignment("Discurso Vida Cr.", vc.discursante, week_id, "main", `vidaCristiana.${i}.discursante`, data);
                        }
                    }
                });
            });

            setAssignmentsByRole(collectedAssignmentsByRole);

            const collectedAssignmentsByPerson: AssignmentsByPerson = {};
            Object.entries(collectedAssignmentsByRole).forEach(([role, persons]) => {
                Object.entries(persons).forEach(([personName, assignments]) => {
                    if (!collectedAssignmentsByPerson[personName]) {
                        collectedAssignmentsByPerson[personName] = [];
                    }
                    assignments.forEach(assignment => {
                        collectedAssignmentsByPerson[personName].push({ ...assignment, role });
                    });
                });
            });
            Object.values(collectedAssignmentsByPerson).forEach(assignments => {
                assignments.sort((a, b) => a.date.localeCompare(b.date));
            });
            setAssignmentsByPerson(collectedAssignmentsByPerson);

            const publisherNames = publishers ? publishers.map(p => p.nombre) : [];
            const assignmentNames = Object.keys(collectedAssignmentsByPerson);
            const allNames = [...new Set([...publisherNames, ...assignmentNames])].sort();
            setAllParticipants(allNames);

            setLoading(false);
        };

        fetchAndProcessData();
    }, [currentCongregation]);

    const handleDownloadPDF = () => {
        if (typeof html2pdf === 'undefined') {
            alert('La función de descarga no está disponible. Por favor, recargue la página.');
            return;
        }
        const element = document.getElementById('future-agenda-container');
        if (!element) return;
        setIsDownloading(true);
        const opt = { margin: 0.5, filename: 'agenda_futura_vmt.pdf', image: { type: 'jpeg', quality: 0.98 }, html2canvas: { scale: 2, useCORS: true }, jsPDF: { unit: 'in', format: 'letter', orientation: 'portrait' } };
        html2pdf().from(element).set(opt).save().then(() => setIsDownloading(false)).catch(() => setIsDownloading(false));
    };

    const handleSendLink = async (participantName: string) => {
        const encodedName = encodeURIComponent(participantName);
        const url = `${window.location.origin}${window.location.pathname}?view=assignments&participant=${encodedName}`;
        try {
            if (navigator.share) {
                await navigator.share({
                    title: 'Tus Asignaciones VMT',
                    text: `Hola ${participantName}, por favor revisa y confirma tus asignaciones aquí:`,
                    url: url,
                });
            } else {
                await navigator.clipboard.writeText(url);
                alert('Enlace copiado al portapapeles.');
            }
        } catch (error) {
            console.error('Error al compartir el enlace:', error);
            alert('No se pudo compartir o copiar el enlace.');
        }
    };

    const StatusIcon: React.FC<{status: AssignmentStatus}> = ({ status }) => {
        switch (status) {
            case 'accepted': return <i className="fas fa-check-circle status-icon status-accepted" title="Aceptada" style={{color:'#10b981'}}></i>;
            case 'rejected': return <i className="fas fa-times-circle status-icon status-rejected" title="Rechazada" style={{color:'#ef4444'}}></i>;
            default: return <i className="fas fa-question-circle status-icon status-pending" title="Pendiente" style={{color:'#cbd5e1'}}></i>;
        }
    };

    const roomMapFull: { [key: string]: string } = { main: "Principal", aux2: "Sala 2", aux3: "Sala 3" };

    // --- LOGIC TO FILTER PARTICIPANTS WITH FUTURE ASSIGNMENTS ---
    const participantsWithFutureAssignments = useMemo(() => {
        return allParticipants
            .filter(person => {
                // Must match search term
                if (searchTerm && !person.toLowerCase().includes(searchTerm.toLowerCase())) {
                    return false;
                }
                // Must have at least one future assignment
                const assignments = assignmentsByPerson[person] || [];
                return assignments.some(a => a.date >= currentWeekStart);
            });
    }, [allParticipants, assignmentsByPerson, currentWeekStart, searchTerm]);

    // Helper component for future assignments agenda
    const FutureAssignmentList: React.FC<{ assignments: PersonAssignment[] }> = ({ assignments }) => {
        // Filter for future dates
        const futureAssignments = assignments.filter(a => a.date >= currentWeekStart);

        if (futureAssignments.length === 0) return null;

        return (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '0' }}>
                {futureAssignments.map((a, idx) => (
                    <div key={idx} style={{ 
                        display: 'flex', 
                        alignItems: 'center', 
                        padding: '10px 16px', 
                        borderBottom: '1px solid var(--border-color)',
                        backgroundColor: 'var(--card-bg-color)'
                    }}>
                        <div style={{ width: '60px', textAlign: 'center', marginRight: '15px' }}>
                            <div style={{ fontWeight: '800', fontSize: '0.85rem', color: 'var(--text-color)', lineHeight: 1.1 }}>{getFridayFromWeekId(a.date, 'short')}</div>
                            <div style={{ marginTop: '4px' }}><StatusIcon status={a.status} /></div>
                        </div>
                        <div style={{ flex: 1 }}>
                            <div style={{ fontWeight: '600', color: 'var(--text-color)', fontSize: '0.95rem' }}>{a.role}</div>
                            <div style={{ display: 'flex', gap: '8px', alignItems: 'center', marginTop: '2px' }}>
                                <span style={{ 
                                    fontSize: '0.75rem', 
                                    color: 'white', 
                                    padding: '2px 6px', 
                                    borderRadius: '4px',
                                    fontWeight: '700',
                                    backgroundColor: a.room === 'main' ? '#3b82f6' : (a.room === 'aux2' ? '#10b981' : '#f59e0b')
                                }}>
                                    {roomMapFull[a.room]}
                                </span>
                                {a.subRole && (
                                    <span style={{ 
                                        fontSize: '0.75rem', 
                                        padding: '2px 6px', 
                                        borderRadius: '4px', 
                                        backgroundColor: 'var(--bg-color)', 
                                        border: '1px solid var(--border-color)',
                                        fontWeight: '600',
                                        color: 'var(--text-color-light)'
                                    }}>
                                        {a.subRole === 'E' ? 'Encargado' : 'Ayudante'}
                                    </span>
                                )}
                            </div>
                        </div>
                    </div>
                ))}
            </div>
        );
    };

    return (
        <div id="filters-container" className="container mx-auto px-4 py-8">
            <h2 className="page-title">Agenda Futura</h2>
            <p style={{marginBottom: '20px', color: 'var(--text-color-light)'}}>
                Mostrando asignaciones desde la semana actual en adelante.
            </p>

            <div style={{ display: 'flex', gap: '10px', marginBottom: '25px', flexWrap: 'wrap' }}>
                <div style={{ flex: 1, position: 'relative', minWidth: '200px' }}>
                    <input 
                        type="text" 
                        placeholder="Buscar participante..." 
                        value={searchTerm}
                        onChange={e => setSearchTerm(e.target.value)}
                        style={{
                            width: '100%',
                            padding: '12px 16px',
                            paddingLeft: '40px',
                            borderRadius: '12px',
                            border: '1px solid var(--border-color)',
                            backgroundColor: 'var(--input-bg)',
                            fontSize: '1rem'
                        }}
                    />
                    <i className="fas fa-search" style={{ position: 'absolute', left: '14px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-color-light)' }}></i>
                </div>
                {participantsWithFutureAssignments.length > 0 && (
                    <button 
                        onClick={handleDownloadPDF} 
                        disabled={isDownloading}
                        className="button"
                        style={{ backgroundColor: 'var(--card-bg-color)', color: 'var(--text-color)', border: '1px solid var(--border-color)', boxShadow: 'var(--shadow-sm)' }}
                    >
                        <i className={`fas ${isDownloading ? 'fa-spinner fa-spin' : 'fa-file-pdf'} mr-2`}></i> 
                        {isDownloading ? 'Generando...' : 'Descargar PDF'}
                    </button>
                )}
            </div>

            {loading ? (
                <div style={{textAlign:'center', padding:'40px', color:'var(--text-color-light)'}}>Cargando agenda...</div>
            ) : participantsWithFutureAssignments.length > 0 ? (
                <div id="future-agenda-container" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '20px' }}>
                    {participantsWithFutureAssignments.map(person => (
                        <div key={person} className="participant-card" style={{ backgroundColor: 'var(--card-bg-color)', borderRadius: '16px', border: '1px solid var(--border-color)', overflow: 'hidden', boxShadow: 'var(--shadow-sm)' }}>
                            <div className="participant-card__header" style={{ padding: '16px', backgroundColor: 'var(--bg-color)', borderBottom: '1px solid var(--border-color)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                <span className="participant-name" style={{ fontWeight: '800', fontSize: '1.1rem', color: 'var(--text-color)' }}>{person}</span>
                                <button className="participant-share-btn" onClick={() => handleSendLink(person)} style={{ background: 'white', border: '1px solid var(--border-color)', width: '32px', height: '32px', borderRadius: '50%', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--primary-color)' }}>
                                    <i className="fas fa-share-alt"></i>
                                </button>
                            </div>
                            <FutureAssignmentList assignments={assignmentsByPerson[person] || []} />
                        </div>
                    ))}
                </div>
            ) : (
                <div style={{ textAlign: 'center', padding: '40px', backgroundColor: 'var(--card-bg-color)', borderRadius: '12px', border: '2px dashed var(--border-color)' }}>
                    <i className="fas fa-calendar-check" style={{ fontSize: '2rem', color: 'var(--text-color-light)', marginBottom: '10px' }}></i>
                    <p style={{ color: 'var(--text-color-light)' }}>
                        {searchTerm ? 'No se encontraron participantes con ese nombre.' : 'No hay asignaciones futuras pendientes.'}
                    </p>
                </div>
            )}
        </div>
    );
};

export default FiltrosAvanzados;

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { useCongregation } from '../lib/CongregationContext';

// Pestañas disponibles en el sistema
export const ALL_TABS = [
    "Inicio",
    "Recordatorios",
    "Programa",
    "Gestionar Participantes",
    "Grupo de Congregación",
    "Filtros Avanzados",
    "Respuestas de Asignaciones",
    "Informes",
    "Planificador",
    "Asignar Anc. y Min.",
    "Configuración"
];

type TabPermission = {
    name: string;
    access: 'view' | 'edit';
};

type AccessConfig = {
    id: string;
    label: string;
    responsible_name: string;
    visible_tabs: TabPermission[];
    access_token: string;
    restricted_group_id?: number | null;
    created_at: string;
    congregation_id?: number;
};

interface ConfiguracionAccesoProps {
    onSimulate?: (config: any) => void;
    isSuperAdmin?: boolean;
    isReadOnly?: boolean;
}

const ConfiguracionAcceso: React.FC<ConfiguracionAccesoProps> = ({ onSimulate, isSuperAdmin = false, isReadOnly = false }) => {
    const { currentCongregation, refreshCongregations } = useCongregation();
    const [configs, setConfigs] = useState<AccessConfig[]>([]);
    const [groups, setGroups] = useState<{id: number, nombre: string}[]>([]);
    const [loading, setLoading] = useState(true);
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    // Configuración General (Salas)
    const [enabledRooms, setEnabledRooms] = useState({ main: true, aux2: true, aux3: true });
    const [loadingSettings, setLoadingSettings] = useState(false);

    // Estado del Formulario
    const [label, setLabel] = useState('');
    const [responsible, setResponsible] = useState('');
    const [password, setPassword] = useState(''); // Acts as "New Password" when editing
    const [oldPasswordInput, setOldPasswordInput] = useState(''); // New state for verification
    const [restrictedGroupId, setRestrictedGroupId] = useState<string>('');
    const [selectedTabs, setSelectedTabs] = useState<TabPermission[]>([
        { name: "Inicio", access: "view" },
        { name: "Programa", access: "view" }
    ]);
    const [editingId, setEditingId] = useState<string | null>(null);

    useEffect(() => {
        if (currentCongregation) {
            fetchConfigs();
            fetchGroups();
            if (currentCongregation.settings?.enabled_rooms) {
                setEnabledRooms(currentCongregation.settings.enabled_rooms);
            }
        }
    }, [currentCongregation]);

    const fetchGroups = async () => {
        if (!currentCongregation) return;
        const { data } = await supabase.from('grupos')
            .select('id, nombre')
            .eq('congregation_id', currentCongregation.id)
            .order('nombre');
        if (data) setGroups(data);
    };

    const fetchConfigs = async () => {
        if (!currentCongregation) return;
        setLoading(true);
        const { data, error } = await supabase.from('access_configs')
            .select('*')
            .eq('congregation_id', currentCongregation.id)
            .order('created_at', { ascending: false });

        if (!error) {
            // Normalizar datos antiguos si existen
            const normalizedData = (data || []).map(config => ({
                ...config,
                visible_tabs: Array.isArray(config.visible_tabs) 
                    ? config.visible_tabs.map((t: any) => typeof t === 'string' ? { name: t, access: 'view' } : t)
                    : []
            }));
            setConfigs(normalizedData);
        }
        setLoading(false);
    };

    const handleSaveAccess = async () => {
        if (!currentCongregation || isReadOnly) return;

        // Validaciones básicas
        if (!label.trim() || !responsible.trim() || selectedTabs.length === 0) {
            setStatusMessage({ text: 'Faltan campos obligatorios (Nombre, Responsable, Permisos)', type: 'error' });
            return;
        }

        // Si estamos creando, la contraseña es obligatoria
        if (!editingId && !password.trim()) {
            setStatusMessage({ text: 'Debe establecer una contraseña.', type: 'error' });
            return;
        }

        let tokenToSave = password.trim();

        // Lógica de edición segura
        if (editingId) {
            const originalConfig = configs.find(c => c.id === editingId);
            if (!originalConfig) {
                setStatusMessage({ text: 'Error al identificar el usuario.', type: 'error' });
                return;
            }

            // Verificar contraseña antigua
            if (oldPasswordInput !== originalConfig.access_token) {
                setStatusMessage({ text: 'La contraseña antigua es incorrecta.', type: 'error' });
                return;
            }

            // Si el campo de nueva contraseña está vacío, mantenemos la anterior (o forzamos cambio, según preferencia)
            // Aquí asumimos que si puso la antigua correcta y la nueva no está vacía, quiere cambiarla.
            if (password.trim()) {
                tokenToSave = password.trim();
            } else {
                // Si deja la nueva vacía, asumimos que no quiere cambiarla
                tokenToSave = originalConfig.access_token;
            }
        }

        // Chequeo de duplicados (excluyendo el actual si estamos editando)
        const duplicate = configs.find(c => c.access_token === tokenToSave && c.id !== editingId);
        if (duplicate) {
            setStatusMessage({ text: 'Esta contraseña ya está en uso por otro usuario.', type: 'error' });
            return;
        }

        const payload = {
            label: label.trim(),
            responsible_name: responsible.trim(),
            access_token: tokenToSave,
            visible_tabs: selectedTabs,
            restricted_group_id: restrictedGroupId ? parseInt(restrictedGroupId) : null,
            congregation_id: currentCongregation.id
        };

        let error;
        if (editingId) {
            const { error: updateError } = await supabase.from('access_configs').update(payload).eq('id', editingId);
            error = updateError;
        } else {
            const { error: insertError } = await supabase.from('access_configs').insert([payload]);
            error = insertError;
        }

        if (error) {
            setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
        } else {
            setStatusMessage({ text: 'Configuración guardada correctamente', type: 'success' });
            resetForm();
            fetchConfigs();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const toggleTab = (tabName: string) => {
        if (isReadOnly) return;
        setSelectedTabs(prev => {
            const index = prev.findIndex(t => t.name === tabName);
            if (index === -1) {
                // No está, añadir como vista
                return [...prev, { name: tabName, access: 'view' }];
            } else if (prev[index].access === 'view') {
                // Está como vista, cambiar a edición
                const newTabs = [...prev];
                newTabs[index] = { ...newTabs[index], access: 'edit' };
                return newTabs;
            } else {
                // Está como edición, quitar
                return prev.filter(t => t.name !== tabName);
            }
        });
    };

    const resetForm = () => {
        setLabel('');
        setResponsible('');
        setPassword('');
        setOldPasswordInput('');
        setRestrictedGroupId('');
        setSelectedTabs([{ name: "Inicio", access: "view" }, { name: "Programa", access: "view" }]);
        setEditingId(null);
    };

    const handleEditClick = (config: AccessConfig) => {
        setEditingId(config.id);
        setLabel(config.label);
        setResponsible(config.responsible_name);
        // IMPORTANTE: No rellenamos el campo de contraseña por seguridad.
        // El usuario debe introducir la antigua para validar y la nueva para cambiar.
        setPassword(''); 
        setOldPasswordInput('');
        setSelectedTabs(config.visible_tabs);
        setRestrictedGroupId(config.restricted_group_id ? String(config.restricted_group_id) : '');
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    const handleDelete = async (id: string) => {
        if (isReadOnly) return;
        if (!window.confirm('¿Eliminar este acceso?')) return;
        const { error } = await supabase.from('access_configs').delete().eq('id', id);
        if (!error) fetchConfigs();
    };

    const saveGeneralSettings = async () => {
        if (!currentCongregation || isReadOnly) return;
        setLoadingSettings(true);
        const { error } = await supabase.from('congregations')
            .update({ settings: { ...currentCongregation.settings, enabled_rooms: enabledRooms } })
            .eq('id', currentCongregation.id);

        if (!error) {
            setStatusMessage({ text: 'Configuración de salas guardada', type: 'success' });
            await refreshCongregations();
        }
        setLoadingSettings(false);
        setTimeout(() => setStatusMessage(null), 3000);
    };

    return (
        <div className="container mx-auto px-4 py-8">
            <div style={{marginBottom: '20px', padding: '15px', backgroundColor: '#f0f9ff', borderLeft: '4px solid #3b82f6', borderRadius: '4px'}}>
                <h2 style={{margin: '0 0 5px 0', fontSize: '1.2rem', color: '#1e3a8a'}}>
                    {isSuperAdmin ? 'Administrador Global' : `Administración Local: ${currentCongregation?.name || ''}`}
                </h2>
                <p style={{margin: 0, fontSize: '0.9rem', color: '#4b5563'}}>
                    {isReadOnly 
                        ? 'Estás en modo de solo lectura. No puedes crear ni modificar usuarios.' 
                        : 'Puedes crear y gestionar contraseñas de acceso para esta congregación.'}
                </p>
            </div>

            {/* Configuración de Salas */}
            {!isReadOnly && (
                <div style={{ backgroundColor: 'var(--card-bg-color)', padding: '24px', borderRadius: '16px', border: '1px solid var(--border-color)', marginBottom: '30px', boxShadow: 'var(--shadow-md)' }}>
                    <h3 style={{ marginTop: 0, marginBottom: '20px', color: 'var(--primary-color)', fontSize: '1.2rem', fontWeight: '800' }}>
                        <i className="fas fa-door-open mr-2"></i>Salas Activas de la Congregación
                    </h3>
                    <div style={{ display: 'flex', gap: '20px', flexWrap: 'wrap', marginBottom: '20px' }}>
                        {Object.entries({ main: "Auditorio Principal", aux2: "Sala 2", aux3: "Sala 3" }).map(([key, label]) => (
                            <label key={key} style={{ display: 'flex', alignItems: 'center', gap: '10px', cursor: 'pointer', fontSize: '1rem', fontWeight: '600' }}>
                                <input 
                                    type="checkbox" 
                                    checked={enabledRooms[key as keyof typeof enabledRooms]} 
                                    onChange={e => setEnabledRooms(prev => ({ ...prev, [key]: e.target.checked }))}
                                    disabled={key === 'main' || isReadOnly}
                                    style={{ width: '20px', height: '20px', accentColor: 'var(--primary-color)' }}
                                />
                                {label}
                            </label>
                        ))}
                    </div>
                    <button onClick={saveGeneralSettings} disabled={loadingSettings || isReadOnly} className="button-save" style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                        {loadingSettings ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-save"></i>}
                        Guardar Configuración de Salas
                    </button>
                </div>
            )}

            {/* Formulario de Llaves/Contraseñas */}
            {!isReadOnly && (
                <div style={{ backgroundColor: 'var(--card-bg-color)', padding: '24px', borderRadius: '16px', border: editingId ? '2px solid var(--primary-color)' : '1px solid var(--border-color)', marginBottom: '30px', boxShadow: 'var(--shadow-lg)' }}>
                    <h3 style={{ marginTop: 0, marginBottom: '20px', color: 'var(--primary-color)', fontSize: '1.2rem', fontWeight: '800' }}>
                        {editingId ? <><i className="fas fa-edit mr-2"></i>Editar Acceso</> : <><i className="fas fa-key mr-2"></i>Crear Nuevo Acceso</>}
                    </h3>

                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '20px', marginBottom: '25px' }}>
                        <div>
                            <label style={{ display: 'block', fontWeight: '700', marginBottom: '8px', fontSize: '0.85rem', color: 'var(--text-color-light)', textTransform: 'uppercase' }}>Nombre del Perfil</label>
                            <input type="text" value={label} onChange={e => setLabel(e.target.value)} placeholder="Ej: Grupo 1, Ancianos, etc." />
                        </div>
                        <div>
                            <label style={{ display: 'block', fontWeight: '700', marginBottom: '8px', fontSize: '0.85rem', color: 'var(--text-color-light)', textTransform: 'uppercase' }}>Nombre del Responsable</label>
                            <input type="text" value={responsible} onChange={e => setResponsible(e.target.value)} placeholder="Ej: Hno. Pérez" />
                        </div>

                        {/* Logic for Passwords */}
                        {editingId ? (
                            <>
                                <div>
                                    <label style={{ display: 'block', fontWeight: '700', marginBottom: '8px', fontSize: '0.85rem', color: '#ef4444', textTransform: 'uppercase' }}>Contraseña Antigua (Requerido)</label>
                                    <input 
                                        type="password" 
                                        value={oldPasswordInput} 
                                        onChange={e => setOldPasswordInput(e.target.value)} 
                                        placeholder="Verificación necesaria" 
                                        style={{ fontFamily: 'monospace', letterSpacing: '1px', borderColor: '#ef4444' }}
                                    />
                                </div>
                                <div>
                                    <label style={{ display: 'block', fontWeight: '700', marginBottom: '8px', fontSize: '0.85rem', color: '#10b981', textTransform: 'uppercase' }}>Nueva Contraseña (Opcional)</label>
                                    <input 
                                        type="text" 
                                        value={password} 
                                        onChange={e => setPassword(e.target.value)} 
                                        placeholder="Dejar vacío para mantener" 
                                        style={{ fontFamily: 'monospace', letterSpacing: '1px', fontWeight: 'bold' }}
                                    />
                                </div>
                            </>
                        ) : (
                            <div>
                                <label style={{ display: 'block', fontWeight: '700', marginBottom: '8px', fontSize: '0.85rem', color: 'var(--text-color-light)', textTransform: 'uppercase' }}>Contraseña de Acceso</label>
                                <input 
                                    type="text" 
                                    value={password} 
                                    onChange={e => setPassword(e.target.value)} 
                                    placeholder="Ej: 123456" 
                                    style={{ fontFamily: 'monospace', letterSpacing: '1px', fontWeight: 'bold' }}
                                />
                            </div>
                        )}

                        <div>
                            <label style={{ display: 'block', fontWeight: '700', marginBottom: '8px', fontSize: '0.85rem', color: 'var(--text-color-light)', textTransform: 'uppercase' }}>Restringir a Grupo (Opcional)</label>
                            <select value={restrictedGroupId} onChange={e => setRestrictedGroupId(e.target.value)}>
                                <option value="">-- Sin restricción (Todos) --</option>
                                {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                            </select>
                        </div>
                    </div>

                    <div style={{ marginBottom: '25px' }}>
                        <label style={{ display: 'block', fontWeight: '700', marginBottom: '12px', fontSize: '0.85rem', color: 'var(--text-color-light)', textTransform: 'uppercase' }}>
                            Permisos de Pestañas (Clic para alternar: <i className="fas fa-eye text-blue-500"></i> Solo Ver → <i className="fas fa-edit text-green-500"></i> Edición → Desactivar)
                        </label>
                        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
                            {ALL_TABS.map(tab => {
                                const perm = selectedTabs.find(t => t.name === tab);
                                const isActive = !!perm;
                                const isEdit = perm?.access === 'edit';

                                return (
                                    <button
                                        key={tab}
                                        onClick={() => toggleTab(tab)}
                                        style={{
                                            padding: '8px 16px',
                                            borderRadius: '30px',
                                            border: isActive ? (isEdit ? '2px solid #10b981' : '2px solid #3b82f6') : '1px solid var(--border-color)',
                                            backgroundColor: isActive ? (isEdit ? '#dcfce7' : '#dbeafe') : 'transparent',
                                            color: isActive ? (isEdit ? '#065f46' : '#1e40af') : 'var(--text-color-light)',
                                            fontWeight: isActive ? '800' : '500',
                                            cursor: 'pointer',
                                            display: 'flex',
                                            alignItems: 'center',
                                            gap: '6px',
                                            transition: 'all 0.2s'
                                        }}
                                    >
                                        {isActive && <i className={`fas ${isEdit ? 'fa-edit' : 'fa-eye'}`}></i>}
                                        <span>{tab}</span>
                                    </button>
                                );
                            })}
                        </div>
                    </div>

                    <div style={{ display: 'flex', gap: '12px' }}>
                        <button onClick={handleSaveAccess} className="button-save" style={{ flex: 1, padding: '15px' }}>
                            <i className={`fas ${editingId ? 'fa-save' : 'fa-plus'} mr-2`}></i>
                            {editingId ? 'Guardar Cambios' : 'Crear Acceso'}
                        </button>
                        {editingId && <button onClick={resetForm} className="button" style={{ background: '#64748b', color: 'white' }}>Cancelar</button>}
                    </div>
                </div>
            )}

            {/* Listado de Llaves */}
            <h2 style={{ fontSize: '1.4rem', fontWeight: '800', marginBottom: '20px', display: 'flex', alignItems: 'center', gap: '10px' }}>
                <i className="fas fa-users-cog color-primary"></i>Accesos Generados
            </h2>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: '20px' }}>
                {loading ? <p>Cargando...</p> : configs.map(config => (
                    <div key={config.id} style={{ backgroundColor: 'var(--card-bg-color)', borderRadius: '16px', padding: '20px', border: '1px solid var(--border-color)', boxShadow: 'var(--shadow-md)', position: 'relative', display: 'flex', flexDirection: 'column' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '15px' }}>
                            <div style={{ flex: 1 }}>
                                <h3 style={{ margin: 0, fontSize: '1.1rem', fontWeight: '800', color: 'var(--text-color)' }}>{config.label}</h3>
                                <p style={{ margin: '4px 0 0 0', fontSize: '0.9rem', color: 'var(--text-color-light)', fontWeight: '600' }}>
                                    <i className="fas fa-user-circle mr-1"></i>{config.responsible_name}
                                </p>
                            </div>
                            {!isReadOnly && (
                                <div style={{ display: 'flex', gap: '8px' }}>
                                    <button onClick={() => handleEditClick(config)} style={{ border: 'none', background: '#eff6ff', color: '#2563eb', padding: '8px', borderRadius: '8px', cursor: 'pointer' }}><i className="fas fa-pen"></i></button>
                                    <button onClick={() => handleDelete(config.id)} style={{ border: 'none', background: '#fef2f2', color: '#ef4444', padding: '8px', borderRadius: '8px', cursor: 'pointer' }}><i className="fas fa-trash"></i></button>
                                </div>
                            )}
                        </div>

                        <div style={{ backgroundColor: '#f0f9ff', padding: '12px', borderRadius: '12px', marginBottom: '15px', border: '1px solid #bae6fd', textAlign:'center' }}>
                            <div style={{ fontSize: '0.75rem', fontWeight: '800', color: '#0284c7', textTransform: 'uppercase', marginBottom: '4px' }}>CONTRASEÑA</div>
                            {/* Passwords hidden by default in the list */}
                            <div style={{ fontSize: '1.2rem', fontWeight: '900', color: '#0c4a6e', fontFamily:'monospace', letterSpacing:'4px' }}>••••••</div>
                        </div>

                        <div style={{ backgroundColor: 'var(--bg-color)', padding: '12px', borderRadius: '12px', marginBottom: '15px', flex: 1 }}>
                            <div style={{ fontSize: '0.7rem', fontWeight: '800', color: 'var(--text-color-light)', textTransform: 'uppercase', marginBottom: '8px' }}>Pestañas y Acceso:</div>
                            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '5px' }}>
                                {config.visible_tabs.map(t => (
                                    <span key={t.name} style={{ fontSize: '0.7rem', padding: '3px 8px', borderRadius: '6px', backgroundColor: t.access === 'edit' ? '#dcfce7' : '#f1f5f9', color: t.access === 'edit' ? '#059669' : '#64748b', border: `1px solid ${t.access === 'edit' ? '#10b981' : '#e2e8f0'}`, display: 'inline-flex', alignItems: 'center', gap: '4px' }}>
                                        <i className={`fas ${t.access === 'edit' ? 'fa-pen' : 'fa-eye'}`} style={{ fontSize: '0.6rem' }}></i> {t.name}
                                    </span>
                                ))}
                            </div>
                        </div>

                        <div style={{ display: 'flex', gap: '10px' }}>
                            <button 
                                onClick={() => onSimulate && onSimulate(config)}
                                style={{ flex: 1, backgroundColor: 'var(--primary-color)', color: 'white', border: 'none', borderRadius: '10px', padding: '12px', fontWeight: '700', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px' }}
                            >
                                <i className="fas fa-sign-in-alt"></i> Probar Acceso
                            </button>
                        </div>
                    </div>
                ))}
            </div>

            {statusMessage && (
                <div style={{ 
                    position: 'fixed', bottom: '20px', left: '50%', transform: 'translateX(-50%)', 
                    backgroundColor: statusMessage.type === 'error' ? '#ef4444' : (statusMessage.type === 'success' ? '#10b981' : '#3b82f6'), 
                    color: 'white', padding: '12px 24px', borderRadius: '30px', boxShadow: '0 8px 30px rgba(0,0,0,0.2)', 
                    zIndex: 9999, fontWeight: 'bold', animation: 'fadeIn 0.3s ease-out' 
                }}>
                    {statusMessage.text}
                </div>
            )}
        </div>
    );
};

export default ConfiguracionAcceso;

import React, { useState, useRef } from 'react';
import { useCongregation } from '../lib/CongregationContext';

interface HeaderProps {
    navItems: string[];
    activeTab: string;
    setActiveTab: (tab: string) => void;
    theme: 'light' | 'dark';
    toggleTheme: () => void;
    viewMode: 'desktop' | 'mobile';
    toggleViewMode: () => void;
    congregationName?: string;
    accessLabel?: string | null; // Nuevo prop para el nombre del usuario
}

const Header: React.FC<HeaderProps> = ({ navItems, activeTab, setActiveTab, theme, toggleTheme, viewMode, toggleViewMode, congregationName, accessLabel }) => {
    const [isMobileMenuOpen, setMobileMenuOpen] = useState(false);
    const { setCongregation } = useCongregation();

    // Secret tap logic state
    const [tapCount, setTapCount] = useState(0);
    const tapTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    const handleSecretLogoClick = () => {
        if (tapTimeoutRef.current) {
            clearTimeout(tapTimeoutRef.current);
        }

        const newCount = tapCount + 1;
        setTapCount(newCount);

        if (newCount >= 5) {
            setCongregation(null);
            setTapCount(0);
        } else {
            tapTimeoutRef.current = setTimeout(() => {
                setTapCount(0);
            }, 800);
        }
    };

    const actionButtons = (
        <div style={{display:'flex', gap:'10px', alignItems:'center'}}>
            <button onClick={toggleViewMode} className="action-button" title={`Vista ${viewMode === 'desktop' ? 'Móvil' : 'Escritorio'}`}>
                <i className={`fas fa-${viewMode === 'desktop' ? 'mobile-alt' : 'desktop'}`}></i>
            </button>
            <button onClick={toggleTheme} className="action-button" title={`Tema ${theme === 'light' ? 'Oscuro' : 'Claro'}`}>
                <i className={`fas fa-${theme === 'light' ? 'moon' : 'sun'}`}></i>
            </button>
        </div>
    );

    return (
        <header className="app-header">
            <div className="app-header__container">
                <div className="app-header__inner">
                    <div 
                        className="app-header__branding" 
                        onClick={handleSecretLogoClick}
                        title="Cambiar Congregación (5 toques)"
                    >
                        <img 
                            className="app-header__logo" 
                            src="https://images.unsplash.com/photo-1491841550275-ad7854e35ca6?auto=format&fit=crop&q=80&w=150&h=150" 
                            alt="Logo"
                        />
                        <div>
                            <div className="app-header__title">{congregationName || 'Sistema VMT'}</div>
                            {congregationName && <div style={{fontSize:'0.75rem', color:'var(--text-color-light)', fontWeight:'500'}}>Congregación Activa</div>}
                            {/* Mostrar nombre de usuario aquí */}
                            {accessLabel && (
                                <div style={{
                                    fontSize:'0.7rem', 
                                    color:'var(--primary-color)', 
                                    fontWeight:'700', 
                                    marginTop:'2px',
                                    textTransform: 'uppercase',
                                    letterSpacing: '0.5px'
                                }}>
                                    <i className="fas fa-user-circle mr-1"></i>{accessLabel}
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Desktop Nav */}
                    <nav className="app-nav--desktop">
                        <ul className="app-nav__list">
                            {navItems.map((item) => (
                                <li key={item}>
                                    <button
                                        onClick={() => setActiveTab(item)}
                                        className={`app-nav__button ${
                                            activeTab === item ? 'app-nav__button--active' : ''
                                        }`}
                                    >
                                        {item}
                                    </button>
                                </li>
                            ))}
                        </ul>
                    </nav>

                    <div style={{display:'none'}} className="desktop-only">
                        {actionButtons}
                    </div>

                    <div style={{display:'flex', alignItems:'center', gap:'10px'}}>
                         <div className="desktop-only" style={{display:'flex', gap:'10px'}}>
                            {actionButtons}
                         </div>

                         {/* Mobile Menu Button */}
                        <div className="app-nav__mobile-toggle-wrapper">
                            {actionButtons}
                            <button
                                type="button"
                                className="app-nav__mobile-toggle"
                                aria-label="Toggle menu"
                                onClick={() => setMobileMenuOpen(!isMobileMenuOpen)}
                            >
                                <i className={`fas fa-${isMobileMenuOpen ? 'times' : 'bars'}`}></i>
                            </button>
                        </div>
                    </div>
                </div>

                 {/* Mobile Nav */}
                {isMobileMenuOpen && (
                    <nav className="app-nav app-nav--mobile">
                        <ul className="app-nav__list app-nav__list--mobile">
                             {navItems.map((item) => (
                                <li key={item}>
                                    <button
                                        onClick={() => {
                                            setActiveTab(item);
                                            setMobileMenuOpen(false);
                                        }}
                                        className={`app-nav__button ${
                                            activeTab === item ? 'app-nav__button--active' : ''
                                        }`}
                                        style={{ fontSize: '1rem', fontWeight: '600' }}
                                    >
                                        {item}
                                    </button>
                                </li>
                            ))}
                        </ul>
                    </nav>
                )}
            </div>
        </header>
    );
};

